  async function handleImportFileChange(event: ChangeEvent<HTMLInputElement>) {
    const file = event.target.files?.[0]

    if (!file) {
      return
    }

    setActionKey("exercise-import-parse")
    setError(null)
    setNotice(null)

    try {
      const XLSX = await import("xlsx")
      const buffer = await file.arrayBuffer()
      const workbook = XLSX.read(buffer, {
        type: "array",
      })

      if (!workbook.SheetNames.length) {
        throw new Error(locale === "en" ? "The selected file has no worksheets." : "File ─æ╞░ß╗úc chß╗ìn kh├┤ng c├│ worksheet n├áo.")
      }

      const worksheets = workbook.SheetNames.map((sheetName) => {
        const sheet = workbook.Sheets[sheetName]
        const rows = XLSX.utils.sheet_to_json<Array<string | number | null | undefined>>(sheet, {
          blankrows: false,
          defval: "",
          header: 1,
          raw: false,
        })

        const headerRow = rows[0] ?? []
        const columnMap = headerRow.reduce<Partial<Record<keyof typeof EXERCISE_IMPORT_HEADERS, number>>>((result, cell, index) => {
          const column = resolveImportColumn(cell)

          if (column && typeof result[column] !== "number") {
            result[column] = index
          }

          return result
        }, {})

        return {
          columnMap,
          rows,
          sheetName,
        }
      })

      const worksheet =
        worksheets.find((item) => item.sheetName.trim().toLowerCase() === "exercises") ??
        worksheets.find(
          (item) => typeof item.columnMap.exerciseName === "number" && typeof item.columnMap.muscleGroup === "number",
        )

      if (!worksheet || !worksheet.rows.length) {
        throw new Error(locale === "en" ? "The selected file is empty." : "File ─æ╞░ß╗úc chß╗ìn ─æang trß╗æng.")
      }

      const { columnMap, rows } = worksheet
      const missingColumns = [
        typeof columnMap.exerciseName !== "number" ? (locale === "en" ? "exercise_name" : "exercise_name") : null,
        typeof columnMap.muscleGroup !== "number" ? (locale === "en" ? "muscle_group" : "muscle_group") : null,
        typeof columnMap.activityType !== "number" ? "activity_type" : null,
        typeof columnMap.primaryMuscles !== "number" ? "primary_muscles" : null,
        typeof columnMap.secondaryMuscles !== "number" ? "secondary_muscles" : null,
      ].filter(Boolean) as string[]

      if (missingColumns.length > 0) {
        throw new Error(
          locale === "en"
            ? `Missing required columns: ${missingColumns.join(", ")}.`
            : `Thiß║┐u cß╗Öt bß║»t buß╗Öc: ${missingColumns.join(", ")}.`,
        )
      }

      const nextRows: AdminExerciseImportRow[] = []
      const nextIssues: ExerciseImportIssue[] = []

      rows.slice(1).forEach((row, index) => {
        const rowNumber = index + 2
        const exerciseName = String(row[columnMap.exerciseName as number] ?? "").trim()
        const muscleGroup = String(row[columnMap.muscleGroup as number] ?? "").trim()
        const variationNameIndex = columnMap.variationName
        const equipmentIndex = columnMap.equipment
        const isDefaultIndex = columnMap.isDefault
        const sortOrderIndex = columnMap.sortOrder
        const activityType = parseActivityType(row[columnMap.activityType as number])
        const primary = parseMuscleSlugs(row[columnMap.primaryMuscles as number])
        const secondary = parseMuscleSlugs(row[columnMap.secondaryMuscles as number])
        const rawVariationName = typeof variationNameIndex === "number" ? String(row[variationNameIndex] ?? "").trim() : ""
        const variationName = rawVariationName || "Default"
        const equipment = typeof equipmentIndex === "number" ? String(row[equipmentIndex] ?? "").trim() : ""
        const isDefault = typeof isDefaultIndex === "number" ? parseImportBoolean(row[isDefaultIndex]) : variationName === "Default"
        const sortOrder = typeof sortOrderIndex === "number" ? parseImportNumber(row[sortOrderIndex]) : undefined
        const isBlankRow = !exerciseName && !muscleGroup && !rawVariationName && !equipment && !activityType && !primary.muscles.length && !secondary.muscles.length

        if (isBlankRow) {
          return
        }

        if (!exerciseName || !muscleGroup) {
          nextIssues.push({
            message:
              locale === "en"
                ? "Missing exercise_name or muscle_group."
                : "Thiß║┐u exercise_name hoß║╖c muscle_group.",
            rowNumber,
          })
          return
        }

        const overlap = primary.muscles.filter((slug) => secondary.muscles.includes(slug))
        if (!activityType || primary.invalid.length || secondary.invalid.length || overlap.length || (activityType === "strength" && !primary.muscles.length)) {
          nextIssues.push({
            message: `Muscle profile kh├┤ng hß╗úp lß╗ç${primary.invalid.length || secondary.invalid.length ? ` (slug lß║í: ${[...primary.invalid, ...secondary.invalid].join(", ")})` : ""}${overlap.length ? ` (tr├╣ng primary/secondary: ${overlap.join(", ")})` : ""}. Activity types: ${EXERCISE_ACTIVITY_TYPES.join(", ")}; muscle slugs: ${MUSCLE_SLUGS.join(", ")}.`,
            rowNumber,
          })
          return
        }

        nextRows.push({
          activityType,
          exerciseName,
          equipment: equipment || undefined,
          isDefault,
          muscleGroup,
          primaryMuscles: primary.muscles,
          rowNumber,
          sortOrder,
          secondaryMuscles: secondary.muscles,
          variationName,
        })
      })

      if (!nextRows.length && !nextIssues.length) {
        nextIssues.push({
          message: locale === "en" ? "No exercise rows were detected." : "Kh├┤ng t├¼m thß║Ñy d├▓ng b├ái tß║¡p n├áo trong file.",
        })
      }

      setImportFileName(file.name)
      setImportRows(nextRows)
      setImportIssues(nextIssues)
    } catch (importError) {
      setImportFileName(file.name)
      setImportRows([])
      setImportIssues([
        {
          message:
            importError instanceof Error
              ? importError.message
              : locale === "en"
                ? "Unable to parse the selected file."
                : "Kh├┤ng thß╗â ─æß╗ìc file ─æ├ú chß╗ìn.",
        },
      ])
    } finally {
      setActionKey(null)
    }
  }

