  async function handleSyncImportFile(file: File) {

    setActionKey("exercise-sync-preview")
    setError(null)
    setNotice(null)

    try {
      const XLSX = await import("xlsx")
      const buffer = await file.arrayBuffer()
      const workbook = XLSX.read(buffer, { type: "array" })
      const sheetName = workbook.SheetNames.find((n) => n.toLowerCase() === "exercises") ?? workbook.SheetNames[0]
      const sheet = workbook.Sheets[sheetName]

      if (!sheet) {
        setError(locale === "en" ? "No data sheet found." : "Kh├┤ng t├¼m thß║Ñy sheet dß╗» liß╗çu.")
        return
      }

      const raw = XLSX.utils.sheet_to_json<Record<string, unknown>>(sheet)

      const headerMap: Record<string, string> = {}
      if (raw.length > 0) {
        for (const key of Object.keys(raw[0] as object)) {
          const lower = key.toLowerCase().replace(/[_\s]+/g, "_").trim()
          if (lower === "id") headerMap[key] = "id"
          else if (["exercise_name", "exercise", "name", "ten_bai_tap", "ten"].includes(lower)) headerMap[key] = "exerciseName"
          else if (["muscle_group", "musclegroup", "body_part", "bodypart", "nhom_co"].includes(lower)) headerMap[key] = "muscleGroup"
          else if (["variation_name", "variation", "bien_the"].includes(lower)) headerMap[key] = "variationName"
          else if (["equipment", "gear", "device", "dung_cu", "thiet_bi"].includes(lower)) headerMap[key] = "equipment"
        }
      }

      const rows: ExerciseSyncRow[] = []
      for (const row of raw) {
        const mapped: Record<string, string> = {}
        for (const [originalKey, mappedKey] of Object.entries(headerMap)) {
          const val = row[originalKey]
          if (val !== undefined && val !== null && val !== "") {
            mapped[mappedKey] = String(val).trim()
          }
        }
        if (!mapped.exerciseName || !mapped.muscleGroup) continue
        const syncRow: ExerciseSyncRow = {
          exerciseName: mapped.exerciseName,
          muscleGroup: mapped.muscleGroup,
          variationName: mapped.variationName || (mapped.id ? "" : "Default"),
        }
        if (mapped.id) syncRow.id = mapped.id
        if (mapped.equipment) syncRow.equipment = mapped.equipment
        rows.push(syncRow)
      }

      if (rows.length === 0) {
        setError(locale === "en" ? "No valid exercise rows found." : "Kh├┤ng t├¼m thß║Ñy d├▓ng b├ái tß║¡p hß╗úp lß╗ç.")
        return
      }

      const preview = await previewExerciseSyncRequest([rows])
      setSyncRows(rows)
      setSyncPreview(preview)
      setIsSyncReviewOpen(true)
    } catch (syncError) {
      setError(
        syncError instanceof Error
          ? syncError.message
          : locale === "en"
            ? "Unable to process sync file."
            : "Kh├┤ng thß╗â xß╗¡ l├╜ file sync.",
      )
    } finally {
      setActionKey(null)
    }
  }

  async function handleApplySyncChanges() {
    if (syncRows.length === 0) return
    setActionKey("exercise-sync-apply")
    setError(null)
    setNotice(null)

    try {
      const result = await applyExerciseSyncRequest([syncRows])
      const parts: string[] = []
      if (result.addedCount > 0) parts.push(locale === "en" ? `+${result.addedCount} added` : `+${result.addedCount} th├¬m`)
      if (result.modifiedCount > 0) parts.push(locale === "en" ? `${result.modifiedCount} modified` : `${result.modifiedCount} sß╗¡a`)
      if (result.deletedCount > 0) parts.push(locale === "en" ? `${result.deletedCount} deleted` : `${result.deletedCount} xo├í`)
      if (result.skippedModifyCount > 0) parts.push(locale === "en" ? `${result.skippedModifyCount} skipped (conflict)` : `${result.skippedModifyCount} bß╗Å qua (tr├╣ng t├¬n)`)
      if (result.skippedDeleteCount > 0) parts.push(locale === "en" ? `${result.skippedDeleteCount} skipped (in use)` : `${result.skippedDeleteCount} bß╗Å qua (─æang d├╣ng)`)

      setNotice(
        locale === "en"
          ? `Sync completed: ${parts.join(", ")}.`
          : `Sync ho├án tß║Ñt: ${parts.join(", ")}.`,
      )
      setIsSyncReviewOpen(false)
      setSyncPreview(null)
      setSyncRows([])

    } catch (applyError) {
      setError(
        applyError instanceof Error
          ? applyError.message
          : locale === "en"
            ? "Unable to apply sync changes."
            : "Kh├┤ng thß╗â ├íp dß╗Ñng thay ─æß╗òi sync.",
      )
    } finally {
      setActionKey(null)
    }
  }

