"use client"

import { useEffect, useMemo, useRef, useState } from "react"
import { Check, ChevronDown, Search } from "lucide-react"

import { useLocale } from "@/components/providers/locale-provider"
import { Drawer, DrawerContent, DrawerDescription, DrawerHeader, DrawerTitle } from "@/components/ui/drawer"
import { matchesExerciseSearch, sortByExerciseRelevance, sortGroupsByExerciseRelevance } from "@/lib/exercise-search"
import { formatExerciseVariationLabel, formatExerciseVariationMeta } from "@/lib/exercise-display"
import type { ExerciseVariationOption } from "@/lib/types"
import { cn } from "@/lib/utils"

type ExercisePickerProps = {
  disabled?: boolean
  exercises: ExerciseVariationOption[]
  fallbackSelection?: {
    equipment?: string
    exerciseName?: string
    isDefault?: boolean
    muscleGroup?: string
    variationName?: string
  }
  onSelect: (variationId: string) => void
  selectedVariationId: string
}

export function ExercisePicker({
  disabled,
  exercises,
  fallbackSelection,
  onSelect,
  selectedVariationId,
}: ExercisePickerProps) {
  const { messages } = useLocale()
  const [open, setOpen] = useState(false)
  const [isMobile, setIsMobile] = useState(false)
  const [query, setQuery] = useState("")
  const [expandedGroups, setExpandedGroups] = useState<Set<string>>(new Set())
  const containerRef = useRef<HTMLDivElement | null>(null)
  const searchInputRef = useRef<HTMLInputElement | null>(null)

  const selectedExercise = useMemo(
    () => exercises.find((exercise) => exercise.id === selectedVariationId) ?? null,
    [exercises, selectedVariationId],
  )

  const groupedExercises = useMemo(() => {
    const grouped = new Map<string, ExerciseVariationOption[]>()

    for (const exercise of exercises.slice().sort((left, right) => {
      const exerciseNameComparison = left.exerciseName.localeCompare(right.exerciseName)

      if (exerciseNameComparison !== 0) {
        return exerciseNameComparison
      }

      const sortOrderComparison = left.sortOrder - right.sortOrder

      if (sortOrderComparison !== 0) {
        return sortOrderComparison
      }

      return left.variationName.localeCompare(right.variationName)
    })) {
      if (!matchesExerciseSearch(
        [exercise.exerciseName, exercise.variationName, exercise.name, exercise.muscleGroup, exercise.equipment],
        query,
      )) {
        continue
      }

      const groupItems = grouped.get(exercise.muscleGroup) ?? []
      groupItems.push(exercise)
      grouped.set(exercise.muscleGroup, groupItems)
    }

    const groups = Array.from(grouped.entries()).map(([muscleGroup, items]) => ({
      muscleGroup,
      items: sortByExerciseRelevance(items, query, (e) => e.exerciseName),
    }))
    return sortGroupsByExerciseRelevance(groups, query, (g) => g.muscleGroup, (g) => g.items.map((e) => ({ name: e.exerciseName })))
  }, [exercises, query])

  const isSearching = query.trim().length > 0

  useEffect(() => {
    const mediaQuery = window.matchMedia("(max-width: 767px)")
    const syncViewport = () => {
      setIsMobile(mediaQuery.matches)
    }

    syncViewport()
    mediaQuery.addEventListener("change", syncViewport)

    return () => {
      mediaQuery.removeEventListener("change", syncViewport)
    }
  }, [])

  useEffect(() => {
    if (!open) {
      setQuery("")
      return
    }

    setExpandedGroups(selectedExercise ? new Set([selectedExercise.muscleGroup]) : new Set())

    const frame = window.requestAnimationFrame(() => {
      searchInputRef.current?.focus()
    })

    if (isMobile) {
      return () => {
        window.cancelAnimationFrame(frame)
      }
    }

    const handlePointerDown = (event: MouseEvent) => {
      if (containerRef.current?.contains(event.target as Node)) {
        return
      }

      setOpen(false)
    }

    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape") {
        setOpen(false)
      }
    }

    document.addEventListener("mousedown", handlePointerDown)
    document.addEventListener("keydown", handleKeyDown)

    return () => {
      window.cancelAnimationFrame(frame)
      document.removeEventListener("mousedown", handlePointerDown)
      document.removeEventListener("keydown", handleKeyDown)
    }
  }, [isMobile, open, selectedExercise])

  const toggleGroup = (groupName: string) => {
    if (isSearching) {
      return
    }

    setExpandedGroups((current) => {
      const next = new Set(current)

      if (next.has(groupName)) {
        next.delete(groupName)
      } else {
        next.add(groupName)
      }

      return next
    })
  }

  const handleSelectExercise = (exercise: ExerciseVariationOption) => {
    onSelect(exercise.id)
    setExpandedGroups(new Set([exercise.muscleGroup]))
    setQuery("")
    setOpen(false)
  }

  const pickerListClassName = cn(
    "semantic-scrollbar mt-3 space-y-2 overflow-y-auto pr-1 [touch-action:pan-y] [-webkit-overflow-scrolling:touch] [&::-webkit-scrollbar]:w-1.5 [&::-webkit-scrollbar-track]:bg-transparent",
    isMobile ? "min-h-0 flex-1 max-h-none overscroll-contain" : "max-h-[18rem] md:max-h-[20rem]",
  )

  const pickerPanel = (
    <>
      <div className="relative">
        <Search className="pointer-events-none absolute left-3 top-1/2 h-4 w-4 -translate-y-1/2 text-muted-foreground" />
        <input
          ref={searchInputRef}
          type="search"
          value={query}
          onChange={(event) => setQuery(event.target.value)}
          placeholder={messages.workoutPage.searchExercisePlaceholder}
          className="border-input placeholder:text-muted-foreground focus-visible:border-ring focus-visible:ring-ring/50 h-10 w-full rounded-xl border bg-background pl-9 pr-3 text-sm outline-none focus-visible:ring-[3px]"
        />
      </div>

      <div className={pickerListClassName}>
        {groupedExercises.length === 0 ? (
          <div className="rounded-2xl border border-dashed border-border/70 px-4 py-5 text-center text-sm text-muted-foreground">
            {messages.workoutPage.noExerciseMatches}
          </div>
        ) : (
          groupedExercises.map((group) => {
            const isExpanded = isSearching || expandedGroups.has(group.muscleGroup)

            return (
              <div key={group.muscleGroup} className="rounded-2xl border border-border/70 bg-muted/10">
                <button
                  type="button"
                  className="flex w-full items-center justify-between gap-3 px-4 py-3 text-left"
                  onClick={() => toggleGroup(group.muscleGroup)}
                >
                  <div className="min-w-0">
                    <p className="truncate text-sm font-semibold text-foreground">{group.muscleGroup}</p>
                    <p className="text-xs text-muted-foreground">
                      {messages.workoutPage.exerciseCount(group.items.length)}
                    </p>
                  </div>
                  <div className="flex items-center gap-3">
                    <span className="rounded-full bg-background px-2.5 py-1 text-micro font-semibold uppercase tracking-[0.16em] text-muted-foreground">
                      {group.items.length}
                    </span>
                    <ChevronDown
                      className={cn(
                        "h-4 w-4 shrink-0 text-muted-foreground transition-transform",
                        isExpanded && "rotate-180",
                      )}
                    />
                  </div>
                </button>

                {isExpanded ? (
                  <div className="space-y-1 border-t border-border/60 px-2 py-2">
                    {group.items.map((exercise) => {
                      const isSelected = exercise.id === selectedVariationId

                      return (
                        <button
                          key={exercise.id}
                          type="button"
                          className={cn(
                            "flex w-full items-start gap-3 rounded-xl px-3 py-2.5 text-left transition-colors",
                            isSelected ? "bg-primary-soft text-primary" : "hover:bg-accent/60",
                          )}
                          onClick={() => handleSelectExercise(exercise)}
                        >
                          <span
                            className={cn(
                              "mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full border",
                              isSelected ? "border-primary bg-primary text-primary-foreground" : "border-border bg-background",
                            )}
                          >
                            {isSelected ? <Check className="h-3.5 w-3.5" /> : null}
                          </span>
                          <span className="min-w-0 flex-1">
                            <span className="block truncate text-sm font-medium">{exercise.exerciseName}</span>
                            <span className="block text-xs text-muted-foreground">
                              {formatExerciseVariationMeta({
                                equipment: exercise.equipment,
                                isDefault: exercise.isDefault,
                                muscleGroup: exercise.muscleGroup,
                                variationName: exercise.variationName,
                              })}
                            </span>
                          </span>
                        </button>
                      )
                    })}
                  </div>
                ) : null}
              </div>
            )
          })
        )}
      </div>
    </>
  )

  return (
    <div ref={containerRef} className="relative z-20 min-w-0">
      <button
        type="button"
        className={cn(
          "flex min-h-12 w-full items-center justify-between gap-3 rounded-xl border border-border/70 bg-background/90 px-4 py-2 text-left shadow-none transition-colors",
          disabled ? "cursor-not-allowed opacity-60" : "hover:border-primary/25",
          open && "border-primary/35 ring-2 ring-primary/10",
        )}
        onClick={() => {
          if (!disabled) {
            setOpen((current) => !current)
          }
        }}
        aria-expanded={open}
        aria-haspopup="listbox"
        disabled={disabled}
      >
        <span className="min-w-0 flex-1">
          <span
            className={cn(
              "block truncate text-sm sm:text-base",
              selectedExercise || fallbackSelection ? "text-foreground" : "text-muted-foreground",
            )}
          >
            {selectedExercise
              ? formatExerciseVariationLabel({
                  exerciseName: selectedExercise.exerciseName,
                  isDefault: selectedExercise.isDefault,
                  variationName: selectedExercise.variationName,
                })
              : fallbackSelection
                ? formatExerciseVariationLabel({
                    exerciseName: fallbackSelection.exerciseName,
                    isDefault: fallbackSelection.isDefault,
                    variationName: fallbackSelection.variationName,
                  })
              : messages.workoutPage.chooseExercise}
          </span>
          {selectedExercise || fallbackSelection ? (
            <span className="block truncate text-xs text-muted-foreground">
              {selectedExercise
                ? formatExerciseVariationMeta({
                    equipment: selectedExercise.equipment,
                    isDefault: selectedExercise.isDefault,
                    muscleGroup: selectedExercise.muscleGroup,
                    variationName: selectedExercise.variationName,
                  })
                : formatExerciseVariationMeta({
                    equipment: fallbackSelection?.equipment,
                    isDefault: fallbackSelection?.isDefault,
                    muscleGroup: fallbackSelection?.muscleGroup,
                    variationName: fallbackSelection?.variationName,
                  })}
            </span>
          ) : null}
        </span>
        <ChevronDown className={cn("h-4 w-4 shrink-0 text-muted-foreground transition-transform", open && "rotate-180")} />
      </button>

      {open && isMobile ? (
        <Drawer open={open} onOpenChange={setOpen}>
              <DrawerContent className="z-[100] max-h-[82svh] overflow-hidden rounded-t-[28px] border-t border-border bg-background/98" overlayClassName="z-[100]">
            <DrawerHeader className="px-4 pt-4 text-left">
              <DrawerTitle>{messages.workoutPage.chooseExercise}</DrawerTitle>
              <DrawerDescription>{messages.workoutPage.chooseExerciseDescription}</DrawerDescription>
            </DrawerHeader>
            <div className="flex min-h-0 flex-1 flex-col px-4 pb-5">
              {pickerPanel}
            </div>
          </DrawerContent>
        </Drawer>
      ) : null}

      {open && !isMobile ? (
        <div className="absolute inset-x-0 bottom-full mb-3 rounded-3xl border border-border/70 bg-background/95 p-3 shadow-[var(--glass-shadow)] backdrop-blur-sm">
          {pickerPanel}
        </div>
      ) : null}
    </div>
  )
}

"use client"

import Link from "next/link"
import { Dumbbell, LogOut, MoreHorizontal, Settings, X } from "lucide-react"
import { Fragment, Suspense, useEffect, useRef, useState } from "react"
import { usePathname, useRouter, useSearchParams } from "next/navigation"
import type { AppRole } from "@/lib/auth/types"
import { LanguageToggle } from "@/components/layout/language-toggle"
import { ThemeToggle } from "@/components/layout/theme-toggle"
import { useAuth } from "@/components/providers/auth-provider"
import { useLocale } from "@/components/providers/locale-provider"
import {
  getAdminNavItems,
  getCoachNavItems,
  getTraineeNavItems,
  isNavItemActive,
  type ShellNavItem,
} from "@/components/layout/shell-nav"
import { cn } from "@/lib/utils"
import { useLiquidGlass } from "@/components/ui/use-liquid-glass"
import { useTheme } from "@/components/providers/theme-provider"

const ROLE_BADGE: Partial<Record<AppRole, string>> = {
  admin: "Admin",
  coach: "Coach",
}

/* ------------------------------------------------------------------ */
/* NavItems ΓÇö needs useSearchParams so must stay in its own component  */
/* ------------------------------------------------------------------ */
function NavItems({
  items,
  role,
  onSelect,
}: {
  items: ShellNavItem[]
  role: AppRole
  onSelect: () => void
}) {
  const pathname = usePathname()
  const searchParams = useSearchParams()
  const currentSection = searchParams.get("s")

  function isActive(item: ShellNavItem): boolean {
    if (role === "admin" && item.href.includes("?s=")) {
      const section = new URLSearchParams(item.href.split("?")[1]).get("s")
      return pathname === "/admin" && currentSection === section
    }
    if (role === "admin" && item.href === "/admin") {
      return pathname === "/admin" && !currentSection
    }
    return isNavItemActive(pathname, item)
  }

  return (
    <>
      {items.map((item) => (
        <Link
          key={item.href}
          href={item.href}
          onClick={onSelect}
          className={cn(
            "flex items-center gap-3 rounded-md px-3 py-2.5 text-sm transition-colors",
            isActive(item)
              ? "bg-muted font-medium text-foreground"
              : "text-muted-foreground hover:bg-muted/60 hover:text-foreground",
          )}
        >
          <item.icon className="h-4 w-4 shrink-0" strokeWidth={1.5} />
          <span>{item.label}</span>
          {item.count != null ? (
            <span className="ml-auto rounded-full bg-muted px-2 py-0.5 font-mono text-micro leading-none text-muted-foreground">
              {item.count}
            </span>
          ) : null}
        </Link>
      ))}
    </>
  )
}

/* ------------------------------------------------------------------ */
/* ShellHeader                                                          */
/* ------------------------------------------------------------------ */
export function ShellHeader({ role = "trainee" }: { role?: AppRole }) {
  const { messages } = useLocale()
  const { resolvedTheme } = useTheme()
  const { signOut } = useAuth()
  const router = useRouter()
  const pathname = usePathname()
  const [open, setOpen] = useState(false)
  const [isSigningOut, setIsSigningOut] = useState(false)
  const mobileNavRef = useRef<HTMLElement>(null)

  useLiquidGlass(
    mobileNavRef,
    {
      blurAmount: 0.4,
      refraction: 0.72,
      chromAberration: 0.05,
      edgeHighlight: 0.14,
      specular: 0.12,
      fresnel: 0.9,
      cornerRadius: 32,
      zRadius: 28,
      brightness: -0.08,
      saturation: 0.12,
      shadowOpacity: 0.24,
      shadowSpread: 12,
    },
    resolvedTheme,
  )

  // Auto-close when the route changes (e.g. after clicking a nav link)
  useEffect(() => {
    setOpen(false)
  }, [pathname])

  // Build nav items per role
  // For admin, exclude /profile from the nav list ΓÇö it's shown in the footer section
  const navItems =
    role === "admin"
      ? getAdminNavItems(messages).filter((item) => !item.href.startsWith("/profile"))
      : role === "coach"
        ? getCoachNavItems(messages)
        : getTraineeNavItems(messages)

  const badge = ROLE_BADGE[role]
  const primaryItems = navItems.slice(0, 4)

  const handleSignOut = async () => {
    setIsSigningOut(true)
    setOpen(false)
    try {
      await signOut()
      router.push("/")
    } finally {
      setIsSigningOut(false)
    }
  }

  return (
    <Fragment>
      <div className="mobile-liquid-glass-root fixed bottom-[calc(0.75rem+env(safe-area-inset-bottom))] left-1/2 z-50 w-[calc(100%-2rem)] max-w-[390px] -translate-x-1/2 md:hidden">
        <div aria-hidden="true" className="mobile-liquid-glass-scene pointer-events-none absolute inset-0 rounded-full" />
        <nav ref={mobileNavRef} className="mobile-floating-nav glass-surface relative grid w-full grid-cols-5 rounded-full border border-border bg-background/45 px-2 py-2 shadow-2xl backdrop-blur-xl">
          {primaryItems.map((item) => {
            const active = isNavItemActive(pathname, item)
            const visuallyActive = active && !open
            return (
              <Link key={item.href} href={item.href} aria-current={active ? "page" : undefined} aria-label={item.label} title={item.label} className={cn("flex min-w-0 items-center justify-center rounded-full px-1 py-2.5 transition-all", visuallyActive ? "bg-primary-soft text-primary shadow-[inset_0_1px_0_var(--glass-rim-soft)]" : "text-muted-foreground hover:bg-muted/60 hover:text-foreground")}>
                <item.icon className="h-5 w-5" strokeWidth={1.7} />
                <span className="sr-only">{item.label}</span>
              </Link>
            )
          })}
          <button type="button" aria-controls="mobile-more-navigation" aria-expanded={open} aria-label={open ? messages.common.closeNavigation : messages.common.openNavigation} title={open ? messages.common.closeNavigation : messages.common.openNavigation} onClick={() => setOpen((value) => !value)} className={cn("flex min-w-0 items-center justify-center rounded-full px-1 py-2.5 transition-all", open ? "bg-primary-soft text-primary shadow-[inset_0_1px_0_var(--glass-rim-soft)]" : "text-muted-foreground hover:bg-muted/60 hover:text-foreground")}>
            <MoreHorizontal className="h-5 w-5" />
            <span className="sr-only">More</span>
          </button>
        </nav>
      </div>

      {/* ΓöÇΓöÇ Dropdown ΓöÇΓöÇ */}
      {open ? (
        <>
          <button
            type="button"
            aria-label={messages.common.closeNavigation}
            onClick={() => setOpen(false)}
            className="fixed inset-0 z-40 bg-background/45 backdrop-blur-[2px]"
          />
          <nav id="mobile-more-navigation" className="glass-surface fixed bottom-[calc(5.75rem+env(safe-area-inset-bottom))] left-3 right-3 z-50 max-h-[calc(100dvh-7rem-env(safe-area-inset-bottom))] overflow-y-auto rounded-3xl border border-border bg-background p-2.5 shadow-2xl">
            <div className="mb-2 flex items-center justify-between px-2 py-1.5">
              <div className="flex items-center gap-2"><Dumbbell className="h-4 w-4" /><span className="font-semibold">YeahBuddy</span>{badge ? <span className="label-micro">{badge}</span> : null}</div>
              <button type="button" onClick={() => setOpen(false)} className="rounded-full p-2 text-muted-foreground hover:bg-muted"><X className="h-4 w-4" /></button>
            </div>
            {/* Role nav items */}
            <Suspense fallback={null}>
              <NavItems items={navItems} role={role} onSelect={() => setOpen(false)} />
            </Suspense>

            {/* ΓöÇΓöÇ Footer section: settings + logout ΓöÇΓöÇ */}
            <div className="my-2 h-px bg-border" />

            <div className="px-3 py-2">
              <p className="mb-1.5 font-mono text-micro font-medium uppercase tracking-[0.08em] text-muted-foreground">
                {messages.common.language}
              </p>
              <LanguageToggle variant="select" />
            </div>

            <div className="px-3 py-2">
              <p className="mb-1.5 font-mono text-micro font-medium uppercase tracking-[0.08em] text-muted-foreground">
                {messages.common.theme}
              </p>
              <ThemeToggle variant="select" />
            </div>

            <Link
              href="/profile"
              onClick={() => setOpen(false)}
              className="flex items-center gap-3 rounded-md px-3 py-2.5 text-sm text-muted-foreground transition-colors hover:bg-muted/60 hover:text-foreground"
            >
              <Settings className="h-4 w-4 shrink-0" strokeWidth={1.5} />
              <span>{messages.common.settings}</span>
            </Link>

            <button
              type="button"
              onClick={() => void handleSignOut()}
              disabled={isSigningOut}
              className="flex w-full items-center gap-3 rounded-md px-3 py-2.5 text-sm text-muted-foreground transition-colors hover:bg-destructive-soft hover:text-destructive-text disabled:opacity-50"
            >
              <LogOut className="h-4 w-4 shrink-0" strokeWidth={1.5} />
              <span>{isSigningOut ? messages.common.signingOut : messages.common.signOut}</span>
            </button>
          </nav>
        </>
      ) : null}
    </Fragment>
  )
}

"use client"

import type { ChangeEvent } from "react"

import { useEffect, useRef, useState } from "react"
import { AlertTriangle, Bell, Camera, ChevronDown, Flame, Loader2, Lock, Monitor, Palette, Phone, Save, Scale, Trash2, User } from "lucide-react"

import { useAuth } from "@/components/providers/auth-provider"
import { useLocale } from "@/components/providers/locale-provider"
import { ThemeToggle } from "@/components/layout/theme-toggle"
import { Avatar, AvatarFallback, AvatarImage } from "@/components/ui/avatar"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select"
import { Switch } from "@/components/ui/switch"
import { forgotPasswordRequest } from "@/lib/auth/api"
import type { AppActivityLevel, AppProfile, AppSex } from "@/lib/auth/types"
import { useResetTraineeData } from "@/lib/queries/profile"
import { useCreateWeightEntry, useWeightEntries } from "@/lib/queries/progress"
import type { BodyMetricEntry } from "@/lib/fitness/types"
import { getAppBaseUrl } from "@/lib/supabase/config"

const availableGoalValues = ["Build Muscle", "Lose Weight", "Increase Strength", "Improve Endurance", "Flexibility"] as const
const DEFAULT_DAILY_CALORIE_GOAL = 2500
const MIN_DAILY_CALORIE_GOAL = 500
const MAX_DAILY_CALORIE_GOAL = 10000
const MAX_AVATAR_FILE_SIZE_BYTES = 2 * 1024 * 1024
const ALLOWED_AVATAR_TYPES = new Set(["image/jpeg", "image/png", "image/webp"])
const MIN_HEIGHT_CM = 50
const MAX_HEIGHT_CM = 300
const MIN_TARGET_WEIGHT_KG = 20
const MAX_TARGET_WEIGHT_KG = 500
const KG_TO_LBS = 2.20462

function convertWeightFromKg(weightKg: number, unit: "kg" | "lbs") {
  return unit === "lbs" ? weightKg * KG_TO_LBS : weightKg
}

function convertWeightToKg(weight: number, unit: "kg" | "lbs") {
  return unit === "lbs" ? weight / KG_TO_LBS : weight
}

function formatNumericInput(value: number, fractionDigits = 1) {
  const rounded = Number(value.toFixed(fractionDigits))
  return Number.isInteger(rounded) ? String(rounded) : String(rounded)
}

function readFileAsDataUrl(file: File) {
  return new Promise<string>((resolve, reject) => {
    const reader = new FileReader()

    reader.onload = () => {
      if (typeof reader.result === "string") {
        resolve(reader.result)
        return
      }

      reject(new Error("avatar_read_failed"))
    }

    reader.onerror = () => {
      reject(new Error("avatar_read_failed"))
    }

    reader.readAsDataURL(file)
  })
}

export type ProfileClientInitialData = {
  profile: AppProfile
  weightEntries: BodyMetricEntry[]
}

export function ProfileClient({ initialData }: { initialData: ProfileClientInitialData }) {
  const { messages } = useLocale()
  const { isLoading, profile: authProfile, session, updateProfile, uploadAvatar } = useAuth()
  const profile = authProfile ?? initialData.profile
  const resetData = useResetTraineeData()
  const weightQuery = useWeightEntries(365, { initialData: initialData.weightEntries })
  const createWeightEntry = useCreateWeightEntry()
  const avatarInputRef = useRef<HTMLInputElement | null>(null)
  const previousWeightUnitRef = useRef<"kg" | "lbs">("kg")
  const [name, setName] = useState("")
  const [phone, setPhone] = useState("")
  const [selectedGoals, setSelectedGoals] = useState<string[]>([])
  const [preferredWeightUnit, setPreferredWeightUnit] = useState<"kg" | "lbs">("kg")
  const [heightCm, setHeightCm] = useState("")
  const [currentWeight, setCurrentWeight] = useState("")
  const [targetWeight, setTargetWeight] = useState("")
  const [syncedWeightKg, setSyncedWeightKg] = useState<number | null>(null)
  const [dailyCalorieGoal, setDailyCalorieGoal] = useState(String(DEFAULT_DAILY_CALORIE_GOAL))
  const [birthDate, setBirthDate] = useState("")
  const [sex, setSex] = useState<AppSex | "">("")
  const [activityLevel, setActivityLevel] = useState<AppActivityLevel | "">("")
  const [notifications, setNotifications] = useState(true)
  const [isSaving, setIsSaving] = useState(false)
  const [isUploadingAvatar, setIsUploadingAvatar] = useState(false)
  const [isSendingReset, setIsSendingReset] = useState(false)
  const [isResettingData, setIsResettingData] = useState(false)
  const [resetConfirmation, setResetConfirmation] = useState("")
  const [error, setError] = useState<string | null>(null)
  const [success, setSuccess] = useState<string | null>(null)
  const goalLabels: Record<(typeof availableGoalValues)[number], string> = {
    "Build Muscle": messages.profile.goalBuildMuscle,
    Flexibility: messages.profile.goalFlexibility,
    "Improve Endurance": messages.profile.goalImproveEndurance,
    "Increase Strength": messages.profile.goalIncreaseStrength,
    "Lose Weight": messages.profile.goalLoseWeight,
  }

  useEffect(() => {
    if (!profile) {
      return
    }

    const nextWeightUnit = profile.preferredWeightUnit ?? "kg"
    previousWeightUnitRef.current = nextWeightUnit
    setName(profile.name)
    setPhone(profile.phone ?? "")
    setSelectedGoals(profile.fitnessGoals ?? [])
    setPreferredWeightUnit(nextWeightUnit)
    setHeightCm(profile.heightCm != null ? formatNumericInput(profile.heightCm) : "")
    setTargetWeight(
      profile.targetWeightKg != null ? formatNumericInput(convertWeightFromKg(profile.targetWeightKg, nextWeightUnit)) : "",
    )
    setDailyCalorieGoal(String(profile.dailyCalorieGoal ?? DEFAULT_DAILY_CALORIE_GOAL))
    setBirthDate(profile.birthDate ? profile.birthDate.slice(0, 10) : "")
    setSex(profile.sex ?? "")
    setActivityLevel(profile.activityLevel ?? "")
  }, [profile])

  // The SSR seed replaces the hasConsumedInitialWeight ref: the query renders the
  // seeded entries on the first pass and only goes to the network once they age
  // past staleTime, so the "use the seed exactly once" bookkeeping disappears.
  const weightEntries = weightQuery.data ?? []
  const latestWeightKg =
    weightEntries.find((entry) => typeof entry.weightKg === "number" && Number.isFinite(entry.weightKg))?.weightKg ?? null

  // The weight field is editable, so it cannot simply be derived ΓÇö but it does
  // have to follow the server value when that changes. Adjusting during render
  // is React's documented answer; an effect here would render once with the
  // stale value and cost a second pass.
  if (syncedWeightKg !== latestWeightKg) {
    setSyncedWeightKg(latestWeightKg)
    setCurrentWeight(
      latestWeightKg != null
        // Read the unit from the profile rather than previousWeightUnitRef:
        // touching a ref during render is impure, and the profile is the source
        // that ref is tracking anyway.
        ? formatNumericInput(convertWeightFromKg(latestWeightKg, profile.preferredWeightUnit ?? "kg"))
        : "",
    )
  }

  useEffect(() => {
    const previousUnit = previousWeightUnitRef.current

    if (previousUnit === preferredWeightUnit) {
      return
    }

    setTargetWeight((currentValue) => {
      const parsedValue = Number.parseFloat(currentValue)

      if (!Number.isFinite(parsedValue) || parsedValue <= 0) {
        return currentValue
      }

      const convertedValue = previousUnit === "kg" ? parsedValue * KG_TO_LBS : parsedValue / KG_TO_LBS
      return formatNumericInput(convertedValue)
    })
    setCurrentWeight((currentValue) => {
      const parsedValue = Number.parseFloat(currentValue)

      if (!Number.isFinite(parsedValue) || parsedValue <= 0) {
        return currentValue
      }

      const convertedValue = previousUnit === "kg" ? parsedValue * KG_TO_LBS : parsedValue / KG_TO_LBS
      return formatNumericInput(convertedValue)
    })
    previousWeightUnitRef.current = preferredWeightUnit
  }, [preferredWeightUnit])

  const toggleGoal = (goal: string) => {
    setSelectedGoals((currentGoals) =>
      currentGoals.includes(goal) ? currentGoals.filter((currentGoal) => currentGoal !== goal) : [...currentGoals, goal],
    )
  }

  const handleAvatarUpload = async (event: ChangeEvent<HTMLInputElement>) => {
    const input = event.currentTarget
    const file = input.files?.[0]
    input.value = ""

    if (!file) {
      return
    }

    if (!ALLOWED_AVATAR_TYPES.has(file.type)) {
      setError(messages.profile.avatarInvalidType)
      setSuccess(null)
      return
    }

    if (file.size > MAX_AVATAR_FILE_SIZE_BYTES) {
      setError(messages.profile.avatarTooLarge)
      setSuccess(null)
      return
    }

    setError(null)
    setSuccess(null)
    setIsUploadingAvatar(true)

    try {
      const dataUrl = await readFileAsDataUrl(file)
      await uploadAvatar({
        dataUrl,
        fileName: file.name,
      })

      setSuccess(messages.profile.avatarUpdated)
    } catch (rawError) {
      setError(
        rawError instanceof Error && rawError.message !== "avatar_read_failed"
          ? rawError.message
          : messages.profile.avatarUploadFailed,
      )
    } finally {
      setIsUploadingAvatar(false)
    }
  }

  const handleSave = async () => {
    if (!profile) {
      return
    }

    const parsedDailyCalorieGoal = Number.parseInt(dailyCalorieGoal.trim(), 10)
    const parsedHeightCm = heightCm.trim() === "" ? null : Number.parseFloat(heightCm.trim())
    const parsedCurrentWeight = currentWeight.trim() === "" ? null : Number.parseFloat(currentWeight.trim())
    const parsedTargetWeight = targetWeight.trim() === "" ? null : Number.parseFloat(targetWeight.trim())
    const parsedCurrentWeightKg =
      parsedCurrentWeight == null ? null : Number(convertWeightToKg(parsedCurrentWeight, preferredWeightUnit).toFixed(2))
    const parsedTargetWeightKg =
      parsedTargetWeight == null ? null : Number(convertWeightToKg(parsedTargetWeight, preferredWeightUnit).toFixed(2))

    if (
      !Number.isFinite(parsedDailyCalorieGoal) ||
      parsedDailyCalorieGoal < MIN_DAILY_CALORIE_GOAL ||
      parsedDailyCalorieGoal > MAX_DAILY_CALORIE_GOAL
    ) {
      setError(messages.profile.invalidDailyCalorieGoal)
      setSuccess(null)
      return
    }

    if (
      parsedHeightCm != null &&
      (!Number.isFinite(parsedHeightCm) || parsedHeightCm < MIN_HEIGHT_CM || parsedHeightCm > MAX_HEIGHT_CM)
    ) {
      setError(messages.profile.invalidHeight)
      setSuccess(null)
      return
    }

    if (
      parsedCurrentWeightKg != null &&
      (!Number.isFinite(parsedCurrentWeightKg) ||
        parsedCurrentWeightKg < MIN_TARGET_WEIGHT_KG ||
        parsedCurrentWeightKg > MAX_TARGET_WEIGHT_KG)
    ) {
      setError(messages.profile.invalidCurrentWeight)
      setSuccess(null)
      return
    }

    if (
      parsedTargetWeightKg != null &&
      (!Number.isFinite(parsedTargetWeightKg) ||
        parsedTargetWeightKg < MIN_TARGET_WEIGHT_KG ||
        parsedTargetWeightKg > MAX_TARGET_WEIGHT_KG)
    ) {
      setError(messages.profile.invalidTargetWeight)
      setSuccess(null)
      return
    }

    const trimmedBirthDate = birthDate.trim()
    if (trimmedBirthDate !== "") {
      const parsedBirthDate = new Date(`${trimmedBirthDate}T00:00:00.000Z`)
      const now = new Date()
      if (Number.isNaN(parsedBirthDate.getTime()) || parsedBirthDate > now) {
        setError(messages.profile.invalidBirthDate)
        setSuccess(null)
        return
      }
    }

    setError(null)
    setSuccess(null)
    setIsSaving(true)

    try {
      if (parsedCurrentWeightKg != null && !session?.access_token) {
        throw new Error(messages.profile.notSignedIn)
      }

      const updatedProfile = await updateProfile({
        activityLevel: activityLevel === "" ? null : activityLevel,
        birthDate: trimmedBirthDate === "" ? null : trimmedBirthDate,
        dailyCalorieGoal: parsedDailyCalorieGoal,
        fitnessGoals: selectedGoals,
        heightCm: parsedHeightCm,
        name,
        phone: phone.trim() || null,
        preferredWeightUnit,
        sex: sex === "" ? null : sex,
        targetWeightKg: parsedTargetWeightKg,
      })

      if (updatedProfile) {
        const nextWeightUnit = updatedProfile.preferredWeightUnit ?? "kg"
        previousWeightUnitRef.current = nextWeightUnit
        setName(updatedProfile.name)
        setPhone(updatedProfile.phone ?? "")
        setSelectedGoals(updatedProfile.fitnessGoals ?? [])
        setPreferredWeightUnit(nextWeightUnit)
        setHeightCm(updatedProfile.heightCm != null ? formatNumericInput(updatedProfile.heightCm) : "")
        setTargetWeight(
          updatedProfile.targetWeightKg != null
            ? formatNumericInput(convertWeightFromKg(updatedProfile.targetWeightKg, nextWeightUnit))
            : "",
        )
        setDailyCalorieGoal(String(updatedProfile.dailyCalorieGoal ?? DEFAULT_DAILY_CALORIE_GOAL))
        setBirthDate(updatedProfile.birthDate ? updatedProfile.birthDate.slice(0, 10) : "")
        setSex(updatedProfile.sex ?? "")
        setActivityLevel(updatedProfile.activityLevel ?? "")
      }

      const shouldCreateWeightEntry =
        parsedCurrentWeightKg != null && (latestWeightKg == null || Math.abs(parsedCurrentWeightKg - latestWeightKg) > 0.05)

      let resolvedCurrentWeightKg = latestWeightKg

      if (shouldCreateWeightEntry && session?.access_token) {
        const bodyMetric = await createWeightEntry.mutateAsync({
          recordedAt: new Date().toISOString(),
          weightKg: parsedCurrentWeightKg,
        })

        resolvedCurrentWeightKg = bodyMetric.weightKg ?? parsedCurrentWeightKg
      }

      const resolvedWeightUnit = updatedProfile?.preferredWeightUnit ?? preferredWeightUnit
      const displayWeightKg = resolvedCurrentWeightKg ?? parsedCurrentWeightKg

      setCurrentWeight(
        displayWeightKg != null ? formatNumericInput(convertWeightFromKg(displayWeightKg, resolvedWeightUnit)) : "",
      )

      setSuccess(messages.profile.updated)
    } catch (rawError) {
      setError(rawError instanceof Error ? rawError.message : messages.profile.updateFailed)
    } finally {
      setIsSaving(false)
    }
  }

  const handlePasswordReset = async () => {
    if (!profile?.email) {
      return
    }

    setError(null)
    setSuccess(null)
    setIsSendingReset(true)

    try {
      const redirectUrl = new URL("/auth/callback", getAppBaseUrl())
      redirectUrl.searchParams.set("next", "/reset-password")

      const response = await forgotPasswordRequest({
        identifier: profile.email,
        redirectTo: redirectUrl.toString(),
      })

      setSuccess(response.message ?? messages.profile.resetEmailSent)
    } catch (rawError) {
      setError(
        rawError instanceof Error
          ? rawError.message
          : messages.profile.resetEmailFailed,
      )
    } finally {
      setIsSendingReset(false)
    }
  }

  const handleResetTraineeData = async () => {
    if (!session?.access_token) {
      setError(messages.profile.notSignedIn)
      setSuccess(null)
      return
    }

    if (resetConfirmation.trim().toUpperCase() !== messages.profile.resetDataConfirmationWord.toUpperCase()) {
      setError(messages.profile.resetDataConfirmationMismatch)
      setSuccess(null)
      return
    }

    setError(null)
    setSuccess(null)
    setIsResettingData(true)

    try {
      await resetData.mutateAsync()
      setCurrentWeight("")
      setResetConfirmation("")
      setSuccess(messages.profile.resetDataSuccess)
    } catch (rawError) {
      setError(rawError instanceof Error ? rawError.message : messages.profile.resetDataFailed)
    } finally {
      setIsResettingData(false)
    }
  }

  if (isLoading || !profile) {
    return (
      <div className="flex min-h-[50vh] items-center justify-center">
        <div className="flex items-center gap-2 text-sm text-muted-foreground">
          <Loader2 className="h-4 w-4 animate-spin" />
          {messages.profile.loading}
        </div>
      </div>
    )
  }

  const initials = (name || profile.name)
    .split(" ")
    .filter(Boolean)
    .map((segment) => segment[0])
    .join("")
    .slice(0, 2)
  const isResetConfirmationValid =
    resetConfirmation.trim().toUpperCase() === messages.profile.resetDataConfirmationWord.toUpperCase()

  return (
    <div className="mx-auto w-full max-w-5xl px-4 py-6 md:px-6">
      <div className="mb-5">
        <h1 className="text-3xl font-semibold leading-none tracking-[-0.025em] md:text-4xl">{messages.profile.title}</h1>
        <p className="mt-1.5 text-sm text-muted-foreground">{messages.profile.subtitle}</p>
      </div>

      {error ? (
        <div className="mb-4 rounded-lg border border-destructive/20 bg-destructive-soft p-3 text-sm text-destructive-text">
          {error}
        </div>
      ) : null}

      {success ? (
        <div className="mb-4 rounded-lg border border-primary/20 bg-primary-soft p-3 text-sm text-primary">
          {success}
        </div>
      ) : null}

      <div className="grid gap-4 lg:grid-cols-[minmax(0,1.45fr)_minmax(320px,0.85fr)] lg:items-start lg:gap-5">
        <div className="min-w-0 space-y-4">
      <div className="rounded-2xl border border-border bg-card p-4 sm:p-5">
        <div className="mb-4 flex items-center gap-2">
          <User className="h-5 w-5 text-primary" />
          <h2 className="text-lg font-semibold">{messages.profile.profile}</h2>
        </div>

        <div className="mb-5 flex items-center gap-4 rounded-xl border border-border/70 bg-muted/30 p-3.5">
          <input
            ref={avatarInputRef}
            id="avatar-upload"
            type="file"
            accept="image/png,image/jpeg,image/webp"
            className="hidden"
            onChange={handleAvatarUpload}
            disabled={isUploadingAvatar}
          />

          <div className="relative">
            <Avatar className="h-16 w-16 border-[3px] border-primary/20 sm:h-20 sm:w-20">
              <AvatarImage src={profile.avatar || "/placeholder.svg"} alt={profile.name} />
              <AvatarFallback className="bg-primary-soft text-2xl text-primary">{initials || "YB"}</AvatarFallback>
            </Avatar>

            <Button
              type="button"
              size="icon-sm"
              className="absolute bottom-0 right-0 rounded-full shadow-lg"
              onClick={() => avatarInputRef.current?.click()}
              disabled={isUploadingAvatar}
              title={messages.profile.changeAvatar}
            >
              {isUploadingAvatar ? <Loader2 className="h-4 w-4 animate-spin" /> : <Camera className="h-4 w-4" />}
            </Button>
          </div>

          <div className="min-w-0 text-left">
            <p className="text-sm font-medium">{messages.profile.changeAvatar}</p>
            <p className="text-xs text-muted-foreground">
              {isUploadingAvatar ? messages.profile.avatarUploading : messages.profile.avatarRequirements}
            </p>
