// ---------------------------------------------------------------------------
// Page
// ---------------------------------------------------------------------------

import { AnalyticsDashboard } from "./dashboard/analytics-dashboard"

export type ProgressClientInitialData = {
  workoutCollection?: WorkoutCollection
  calendar: ProgressCalendar
  historyLogs?: WorkoutLog[]
  prevCalendar: ProgressCalendar | null
  programs?: TraineeProgram[]
  viewMonth: number
  viewYear: number
  weekLogs?: WorkoutLog[]
  weightUnitLabel: string
}

export function ProgressClient({ initialData }: { initialData: ProgressClientInitialData }) {
  const workoutsQuery = useWorkouts(initialData.workoutCollection)
  const { isLoading: authLoading, session } = useAuth()
  const { locale, messages } = useLocale()

  // Month navigation
  const now = new Date()
  const [viewYear, setViewYear] = useState(initialData.viewYear)
  const [viewMonth, setViewMonth] = useState(initialData.viewMonth) // 1-based

  const [yearViewYear, setYearViewYear] = useState(now.getFullYear())

  // UI state
  const [tab, setTab] = useState<Tab>("history")
  const [filter, setFilter] = useState<WorkoutKind>("all")

  // Modal
  const [selectedLogId, setSelectedLogId] = useState<string | null>(null)

  // Dashboard date range
  const [dashboardRange] = useState(() => {
    const end = new Date()
    const start = new Date(end)
    start.setDate(end.getDate() - 90)
    return { start, end }
  })

  const token = session?.access_token


  const isSeedMonth = viewYear === initialData.viewYear && viewMonth === initialData.viewMonth
  const calendarQuery = useProgressCalendar(viewYear, viewMonth, {
    initialData: isSeedMonth ? initialData.calendar : undefined,
  })
  const previousQuery = useProgressCalendar(viewMonth === 1 ? viewYear - 1 : viewYear, viewMonth === 1 ? 12 : viewMonth - 1, {
    summaryOnly: true,
    initialData: isSeedMonth ? initialData.prevCalendar : undefined,
    enabled: calendarQuery.isSuccess,
  })
  
  // Dashboard hook replacing the old analytics query
  const dashboardQuery = useDashboardAnalytics(dashboardRange.start, dashboardRange.end, { enabled: tab === "prs" })
  const yearQuery = useProgressYearView(yearViewYear, { enabled: tab === "year" })
  
  const calendar = calendarQuery.data ?? null
  const prevCalendar = previousQuery.data ?? null
  const dashboardData = dashboardQuery.data ?? null
  const yearView = yearQuery.data ?? null
  
  const calendarLoading = calendarQuery.isPending
  const dashboardLoading = dashboardQuery.isPending
  const yearViewLoading = yearQuery.isPending
  const error = (calendarQuery.error ?? dashboardQuery.error ?? yearQuery.error)?.message

  // Month nav helpers
  const goToPrevMonth = useCallback(() => {
    setViewMonth((m) => {
      if (m === 1) { setViewYear((y) => y - 1); return 12 }
      return m - 1
    })
  }, [])

  const goToNextMonth = useCallback(() => {
    setViewMonth((m) => {
      if (m === 12) { setViewYear((y) => y + 1); return 1 }
      return m + 1
    })
  }, [])

  const isCurrentMonth =
    viewYear === now.getFullYear() && viewMonth === now.getMonth() + 1

  // Handle day click in calendar ΓåÆ open modal for first log of that day
  const handleDayClick = useCallback((logs: ProgressCalendarLogStub[]) => {
    if (logs.length > 0) setSelectedLogId(logs[0].id)
  }, [])

  // Handle year-view day click ΓåÆ navigate calendar to that month
  const handleYearDayClick = useCallback((date: string) => {
    const [y, m] = date.split("-").map(Number)
    setViewYear(y)
    setViewMonth(m)
    setTab("history")
  }, [])

  if (authLoading || (calendarLoading && calendar == null)) {
    return <ProgressPageSkeleton />
  }

  return (
    <>
      <div className="mx-auto w-full max-w-5xl px-4 py-6 md:px-6">

        {/* ---- Page header ---- */}
        <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between">
          {/* Month nav */}
          <div className="flex items-center gap-3">
            <button
              type="button"
              onClick={goToPrevMonth}
              className="inline-flex items-center justify-center rounded-lg border border-border p-1.5 pointer-coarse:size-11 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              aria-label={messages.progressPage.previousMonth}
            >
              <ChevronLeft className="h-4 w-4" />
            </button>

            <div>
              <LabelMicro className="mb-1 block">{monthLabel(viewYear, viewMonth, locale)}</LabelMicro>
              <h1 className="text-3xl font-semibold leading-none tracking-[-0.02em] text-foreground">
                {calendarLoading
                  ? "ΓÇö"
                  : messages.workoutPage.sessionCount(calendar?.summary.totalWorkouts ?? 0)
                }
              </h1>
            </div>

            <button
              type="button"
              onClick={goToNextMonth}
              disabled={isCurrentMonth}
              className="inline-flex items-center justify-center rounded-lg border border-border p-1.5 pointer-coarse:size-11 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:pointer-events-none disabled:opacity-30"
              aria-label={messages.progressPage.nextMonth}
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>

          {/* Filter chips + export */}
          <div className="flex flex-wrap items-center gap-2">
            {(["all", "push", "pull", "legs"] as WorkoutKind[]).map((k) => (
              <Chip key={k} active={filter === k} onClick={() => setFilter(k)}>
                {k === "all"
                  ? messages.workoutPage.all
                  : k === "push"
                    ? messages.workoutPage.tagPush
                    : k === "pull"
                      ? messages.workoutPage.tagPull
                      : messages.workoutPage.tagLegs}
              </Chip>
            ))}
            <ExportWorkoutDialog programs={workoutsQuery.data?.programs ?? initialData.programs ?? []} />
          </div>
        </div>

        {/* ---- Stats summary ---- */}
        <div className="mb-6">
          <StatsSummary calendar={calendar} prevCalendar={prevCalendar} />
        </div>

        {/* ---- Tab strip ---- */}
        <div className="mb-6 flex gap-1 border-b border-border">
          {(["history", "year", "prs"] as Tab[]).map((t) => (
            <button
              key={t}
              type="button"
              onClick={() => setTab(t)}
              className={cn(
                "label-micro -mb-px border-b-2 px-4 py-2.5 transition-colors",
                tab === t
                  ? "border-primary text-primary"
                  : "border-transparent text-muted-foreground hover:text-foreground",
              )}
            >
              {t === "history" ? messages.progressPage.historyTab : t === "year" ? messages.progressPage.yearView : "Analytics"}
            </button>
          ))}
        </div>

        {/* ---- Error banner ---- */}
        {error ? (
          <div className="mb-6 rounded-lg border border-destructive/20 bg-destructive-soft px-4 py-3 text-sm text-destructive-text">
            {error}
          </div>
        ) : null}

        {/* ================================================================
            HISTORY TAB
            ================================================================ */}
        {tab === "history" && (
          <div className="grid gap-6 lg:grid-cols-[1fr_360px]">
            <CalendarSection
              year={viewYear}
              month={viewMonth}
              filter={filter}
              calendar={calendar}
              calendarLoading={calendarLoading}
              onDayClick={handleDayClick}
            />

            <div className="space-y-6">
              <TrainedAreasCard
                weekLogs={workoutsQuery.data?.weekLogs ?? initialData.weekLogs ?? []}
                historyLogs={workoutsQuery.data?.historyLogs ?? initialData.historyLogs ?? []}
              />

              <div>
                <LabelMicro className="mb-3 block">{messages.progressPage.recent}</LabelMicro>
                <RecentSessions
                  calendar={calendar}
                  calendarLoading={calendarLoading}
                  onLogClick={setSelectedLogId}
                />
              </div>
            </div>
          </div>
        )}

        {/* ================================================================
            YEAR VIEW TAB
            ================================================================ */}
        {tab === "year" && (
          <div className="space-y-6">
            <div className="flex items-center gap-3">
              <button
                type="button"
                onClick={() => setYearViewYear((y) => y - 1)}
                className="inline-flex items-center justify-center rounded-lg border border-border p-1.5 pointer-coarse:size-11 text-muted-foreground transition-colors hover:bg-muted"
                aria-label={messages.progressPage.previousYear}
              >
                <ChevronLeft className="h-4 w-4" />
              </button>
              <span className="font-mono text-sm font-medium tnum text-foreground">{yearViewYear}</span>
              <button
                type="button"
                onClick={() => setYearViewYear((y) => y + 1)}
                disabled={yearViewYear >= now.getFullYear()}
                className="inline-flex items-center justify-center rounded-lg border border-border p-1.5 pointer-coarse:size-11 text-muted-foreground transition-colors hover:bg-muted disabled:pointer-events-none disabled:opacity-30"
                aria-label={messages.progressPage.nextYear}
              >
                <ChevronRight className="h-4 w-4" />
              </button>
            </div>
            <div className="relative">
              <YearView
                yearView={yearView}
                yearViewLoading={yearViewLoading}
                year={yearViewYear}
                onDayClick={handleYearDayClick}
              />
            </div>
          </div>
        )}

        {/* ================================================================
            PRs TAB
            ================================================================ */}
        {tab === "prs" && (
          dashboardLoading ? (
            <ProgressPrsSkeleton />
          ) : dashboardData ? (
            <AnalyticsDashboard data={dashboardData} />
          ) : (
            <div className="flex min-h-[14rem] items-center justify-center rounded-lg border border-dashed border-border text-sm text-muted-foreground">
              No analytics data available.
            </div>
          )
        )}
      </div>

      {/* ---- Workout log detail modal ---- */}
      {selectedLogId && token && (
        <WorkoutLogModal
          logId={selectedLogId}
          accessToken={token}
          onClose={() => setSelectedLogId(null)}
        />
      )}
    </>
  )
}

"use client"

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState, type ReactNode } from "react"

export type ThemeMode = "light" | "dark" | "system"
export type ResolvedTheme = "light" | "dark"

type ThemeContextValue = {
  resolvedTheme: ResolvedTheme
  setTheme: (nextTheme: ThemeMode) => void
  theme: ThemeMode
}

export const themeStorageKey = "yeahbuddy-theme"
const darkQuery = "(prefers-color-scheme: dark)"
const lightThemeColor = "#f4f7fb"
const darkThemeColor = "#080a0f"
const defaultTheme: ThemeMode = "light"

const ThemeContext = createContext<ThemeContextValue | undefined>(undefined)

function isThemeMode(value: string | null): value is ThemeMode {
  return value === "light" || value === "dark" || value === "system"
}

/**
 * "glass" and "midnight" used to be extra themes. Both were dark-family
 * palettes, so they migrate to dark rather than silently dropping anyone who
 * had them selected back to light. The same migration runs in the pre-paint
 * script in app/layout.tsx, which has to make the identical decision before
 * React boots.
 */
function migrateStoredTheme(value: string | null): ThemeMode {
  if (value === "glass" || value === "midnight") return "dark"
  return isThemeMode(value) ? value : defaultTheme
}

function getStoredTheme(): ThemeMode {
  try {
    const storedTheme = window.localStorage.getItem(themeStorageKey)
    const migrated = migrateStoredTheme(storedTheme)

    if (storedTheme !== null && storedTheme !== migrated) {
      window.localStorage.setItem(themeStorageKey, migrated)
    }

    return migrated
  } catch {
    return defaultTheme
  }
}

function resolveTheme(theme: ThemeMode): ResolvedTheme {
  if (theme !== "system") {
    return theme
  }

  return window.matchMedia?.(darkQuery).matches ? "dark" : "light"
}

const themeColors: Record<ResolvedTheme, string> = {
  light: lightThemeColor,
  dark: darkThemeColor,
}

/**
 * The pre-paint script in app/layout.tsx has to reach the identical result
 * before React boots, so the two must stay in sync.
 */
function applyThemeToDocument(resolvedTheme: ResolvedTheme) {
  const root = document.documentElement
  root.classList.toggle("dark", resolvedTheme !== "light")
  root.style.colorScheme = resolvedTheme

  const themeColor = document.querySelector<HTMLMetaElement>('meta[name="theme-color"]')
  themeColor?.setAttribute("content", themeColors[resolvedTheme])
}

export function ThemeProvider({ children, initialTheme }: { children: ReactNode; initialTheme?: ThemeMode }) {
  const startingTheme = initialTheme ?? defaultTheme
  const [theme, setThemeState] = useState<ThemeMode>(startingTheme)
  const [resolvedTheme, setResolvedTheme] = useState<ResolvedTheme>(
    startingTheme === "system" ? "light" : startingTheme,
  )
  const themeRef = useRef<ThemeMode>(startingTheme)

  const applyTheme = useCallback((nextTheme: ThemeMode) => {
    const nextResolvedTheme = resolveTheme(nextTheme)
    applyThemeToDocument(nextResolvedTheme)
    setResolvedTheme(nextResolvedTheme)
  }, [])

  useEffect(() => {
    const startupTheme = initialTheme ?? getStoredTheme()
    themeRef.current = startupTheme
    setThemeState(startupTheme)
    applyTheme(startupTheme)

    const mediaQuery = window.matchMedia?.(darkQuery)
    if (!mediaQuery) {
      return
    }

    const handleSystemThemeChange = () => {
      if (themeRef.current === "system") {
        applyTheme("system")
      }
    }

    mediaQuery.addEventListener("change", handleSystemThemeChange)
    return () => mediaQuery.removeEventListener("change", handleSystemThemeChange)
  }, [applyTheme, initialTheme])

  const setTheme = useCallback(
    (nextTheme: ThemeMode) => {
      themeRef.current = nextTheme
      setThemeState(nextTheme)

      try {
        window.localStorage.setItem(themeStorageKey, nextTheme)
      } catch {
        // Persisting theme is best-effort; the selected theme still applies for this session.
      }

      applyTheme(nextTheme)
    },
    [applyTheme],
  )

  const value = useMemo<ThemeContextValue>(
    () => ({
      resolvedTheme,
      setTheme,
      theme,
    }),
    [resolvedTheme, setTheme, theme],
  )

  return <ThemeContext.Provider value={value}>{children}</ThemeContext.Provider>
}

export function useTheme() {
  const context = useContext(ThemeContext)

  if (!context) {
    throw new Error("useTheme must be used within ThemeProvider")
  }

  return context
}

"use client"

import { RefreshCw } from "lucide-react"
import { useQueryClient } from "@tanstack/react-query"
import { useEffect, useRef, useState, type ReactNode } from "react"

import { cn } from "@/lib/utils"

const THRESHOLD = 72 // px pulled (after resistance) needed to trigger a refresh
const MAX_PULL = 120 // px ΓÇö visual cap so the spinner never flies off
const RESISTANCE = 0.5 // finger travel ΓåÆ visual travel (rubber-band feel)

interface PullToRefreshProps {
  children: ReactNode
  /**
   * Custom refresh handler. By default revalidates active client queries.
   */
  onRefresh?: () => Promise<void> | void
  className?: string
}

/**
 * Touch-only pull-to-refresh. iOS standalone PWAs lose Safari's native
 * pull-to-refresh, so we rebuild it. Only arms when the active scroll
 * container is already at the top; on desktop (no touch events) it's inert.
 */
export function PullToRefresh({ children, onRefresh, className }: PullToRefreshProps) {
  const queryClient = useQueryClient()
  const [busy, setBusy] = useState(false)
  const [pull, setPull] = useState(0)
  const [dragging, setDragging] = useState(false)

  const refreshing = busy
  const refreshingRef = useRef(refreshing)
  refreshingRef.current = refreshing

  const wrapRef = useRef<HTMLDivElement>(null)
  const startY = useRef<number | null>(null)
  const pullRef = useRef(0)

  // When a refresh cycle ends, settle the indicator back to rest.
  useEffect(() => {
    if (!refreshing) {
      pullRef.current = 0
      setPull(0)
    }
  }, [refreshing])

  useEffect(() => {
    const el = wrapRef.current
    if (!el) return

    // Returns true if the node (or any ancestor up to body) is position:fixed.
    // Used to skip PTR arming when the touch lands inside a modal overlay.
    const isInsideFixedOverlay = (node: EventTarget | null): boolean => {
      let cur = node as HTMLElement | null
      while (cur && cur.nodeType === 1 && cur !== document.body) {
        if (getComputedStyle(cur).position === "fixed") return true
        cur = cur.parentElement
      }
      return false
    }

    // Scroll offset of the nearest scrollable ancestor (handles both
    // document-scroll and an inner `overflow-auto` container).
    const scrollTopOf = (node: EventTarget | null): number => {
      let cur = node as HTMLElement | null
      while (cur && cur.nodeType === 1 && cur !== document.body) {
        const oy = getComputedStyle(cur).overflowY
        if ((oy === "auto" || oy === "scroll") && cur.scrollHeight > cur.clientHeight + 1) {
          return cur.scrollTop
        }
        cur = cur.parentElement
      }
      return window.scrollY || document.documentElement.scrollTop || 0
    }

    const run = async () => {
      setBusy(true)
      try {
        if (onRefresh) {
          await onRefresh()
        } else {
          await queryClient.invalidateQueries()
        }
      } finally {
        setBusy(false)
      }
    }

    const onStart = (e: TouchEvent) => {
      if (refreshingRef.current || e.touches.length !== 1) return
      if (isInsideFixedOverlay(e.target)) return
      startY.current = scrollTopOf(e.target) <= 0 ? e.touches[0].clientY : null
    }

    const onMove = (e: TouchEvent) => {
      if (startY.current === null || refreshingRef.current) return
      const dy = e.touches[0].clientY - startY.current
      if (dy <= 0) {
        if (pullRef.current !== 0) {
          pullRef.current = 0
          setPull(0)
          setDragging(false)
        }
        return
      }
      const dist = Math.min(MAX_PULL, dy * RESISTANCE)
      pullRef.current = dist
      setPull(dist)
      setDragging(true)
      if (dist > 4 && e.cancelable) e.preventDefault() // suppress native bounce
    }

    const onEnd = () => {
      if (startY.current === null) return
      const triggered = pullRef.current >= THRESHOLD
      startY.current = null
      setDragging(false)
      if (triggered) {
        pullRef.current = THRESHOLD
        setPull(THRESHOLD)
        void run()
      } else {
        pullRef.current = 0
        setPull(0)
      }
    }

    el.addEventListener("touchstart", onStart, { passive: true })
    el.addEventListener("touchmove", onMove, { passive: false })
    el.addEventListener("touchend", onEnd, { passive: true })
    el.addEventListener("touchcancel", onEnd, { passive: true })
    return () => {
      el.removeEventListener("touchstart", onStart)
      el.removeEventListener("touchmove", onMove)
      el.removeEventListener("touchend", onEnd)
      el.removeEventListener("touchcancel", onEnd)
    }
  }, [onRefresh, queryClient])

  const visualPull = refreshing ? THRESHOLD : pull
  const progress = Math.min(1, visualPull / THRESHOLD)

  return (
    <div ref={wrapRef} className={cn("relative", className)}>
      <div
        aria-hidden
        className="pointer-events-none fixed inset-x-0 z-[60] flex justify-center"
        style={{
          top: "env(safe-area-inset-top)",
          transform: `translateY(${visualPull - 44}px)`,
          opacity: visualPull > 4 ? 1 : 0,
          transition: dragging ? "none" : "transform .25s ease, opacity .2s ease",
        }}
      >
        <div className="mt-2 flex h-9 w-9 items-center justify-center rounded-full border border-border bg-background shadow-md">
          <RefreshCw
            className={cn("h-4 w-4 text-primary", refreshing && "animate-spin")}
            style={{
              transform: refreshing ? undefined : `rotate(${progress * 270}deg)`,
              opacity: 0.5 + progress * 0.5,
            }}
          />
        </div>
      </div>

      {children}
    </div>
  )
}

"use client"

import Link from "next/link"
import { memo, useEffect, useMemo, useState } from "react"
import { addDays, differenceInMinutes, format, startOfDay } from "date-fns"
import { enUS, vi } from "date-fns/locale"
import { CalendarDays, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, ChevronUp, Loader2, Play, Plus, Search, Trash2, User } from "lucide-react"

import { AddExerciseModal } from "@/components/exercises/add-exercise-modal"
import { useAuth } from "@/components/providers/auth-provider"
import { useLocale } from "@/components/providers/locale-provider"
import { Button } from "@/components/ui/button"
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog"
import { Input } from "@/components/ui/input"
import { WorkoutLogReview, WorkoutPlanPreview } from "@/components/workout/workout-log-review"
import { useQueryClient } from "@tanstack/react-query"
import { useCreateWorkout, useTraineePrograms, useWorkoutDetail, useWorkouts } from "@/lib/queries/workouts"
import { useExercises } from "@/lib/queries/exercises"
import { queryKeys } from "@/lib/queries/keys"
import { userQueryKey } from "@/lib/queries/scoped"
import { resolveEffectiveWeekIndex, resolveProgramWeekForWeekStart } from "@/lib/fitness/program-week"
import { formatRepTarget, parseRepTargetText } from "@/lib/workout-reps"
import { cn } from "@/lib/utils"
import type { CoachProgram, TraineeProgram, WorkoutCollection } from "@/lib/fitness/types"
import type { ExerciseVariationOption, Workout, WorkoutLog, WorkoutScheduleEntry, WeeklySchedule } from "@/lib/types"
import type { AppMessages } from "@/lib/i18n/messages"
import { TAG_DOT_COLOR } from "@/lib/fitness/routine-tag"

type WeeklyCalendarProps = {
  initialData?: WorkoutCollection
  historyLogs?: WorkoutLog[]
  programs?: TraineeProgram[]
  recentLogs: WorkoutLog[]
  schedule: WeeklySchedule
  scheduleEntries?: WorkoutScheduleEntry[]
  showHero?: boolean
  weekLogs?: WorkoutLog[]
  workouts: Workout[]
}

type SourceFilter = "all" | "coach" | "self"
type RoutineKind = "push" | "pull" | "legs" | "full_body" | "cardio" | "other"
type RoutineTag = "push" | "pull" | "legs" | "upper" | "lower" | "full"

type RoutineExercise = {
  fallbackEquipment?: string
  fallbackExerciseName?: string
  fallbackIsDefault?: boolean
  fallbackMuscleGroup?: string
  fallbackVariationName?: string
  id: string
  notes?: string
  reps: string
  rir?: string
  restTime?: string
  sets: number
  variationId: string
  weight: string
}

type Routine = {
  exercises: RoutineExercise[]
  id: string
  name: string
  tag: RoutineTag
}

type ScheduleEntry = WorkoutScheduleEntry

const DISPLAY_WEEKDAY_ORDER = [1, 2, 3, 4, 5, 6, 0]
const ROUTINE_TAGS: RoutineTag[] = ["push", "pull", "legs", "upper", "lower", "full"]


function getRoutineTagLabel(tag: RoutineTag, messages: AppMessages) {
  const labels: Record<RoutineTag, string> = {
    full: messages.workoutPage.tagFull,
    legs: messages.workoutPage.tagLegs,
    lower: messages.workoutPage.tagLower,
    pull: messages.workoutPage.tagPull,
    push: messages.workoutPage.tagPush,
    upper: messages.workoutPage.tagUpper,
  }

  return labels[tag]
}

function createDraftId() {
  if (typeof crypto !== "undefined" && "randomUUID" in crypto) {
    return crypto.randomUUID()
  }

  return `${Date.now()}-${Math.random().toString(16).slice(2)}`
}

// Returns a local-midnight Date whose calendar date (yyyy-MM-dd) matches the
// UTC Monday that starts the week containing `date`. Mirrors backend's
// startOfUtcWeek so frontend and server always agree on the week boundary.
function startOfUtcWeekAsLocal(date: Date): Date {
  const utcDay = date.getUTCDay()
  const offset = utcDay === 0 ? -6 : 1 - utcDay
  const utcMondayMs = Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) + offset * 86_400_000
  const utcMonday = new Date(utcMondayMs)
  return new Date(utcMonday.getUTCFullYear(), utcMonday.getUTCMonth(), utcMonday.getUTCDate())
}

function createEmptyRoutineExercise(defaultVariationId = ""): RoutineExercise {
  return {
    id: createDraftId(),
    reps: "8-12",
    rir: "",
    restTime: "",
    sets: 3,
    variationId: defaultVariationId,
    weight: "",
  }
}

function mapRoutineTagToWorkoutKind(tag: RoutineTag): RoutineKind {
  if (tag === "full" || tag === "upper") return "full_body"
  if (tag === "lower") return "legs"
  return tag
}

function getDateKey(date: Date) {
  return format(date, "yyyy-MM-dd")
}

function isRecurringWorkout(workout: Workout | null): workout is Workout & { scheduledDate?: undefined; scheduledDay: number } {
  return Boolean(workout && !workout.scheduledDate && typeof workout.scheduledDay === "number")
}

function getScheduleOccurrenceKey(workoutId: string, plannedDateKey: string) {
  return `${workoutId}:${plannedDateKey}`
}

function normalizeScheduleMatchText(value: string) {
  return value.trim().toLowerCase().replace(/\s+/g, " ")
}

function getWorkoutCompletionMatchKeys(workout: Pick<Workout, "id" | "name" | "scheduledDay">) {
  const keys = [`id:${workout.id}`]
  const normalizedName = normalizeScheduleMatchText(workout.name)

  if (normalizedName) {
    keys.push(`name:${normalizedName}`)

    if (typeof workout.scheduledDay === "number") {
      keys.push(`day:${workout.scheduledDay}:name:${normalizedName}`)
    }
  }

  return keys
}

function getRecurringWorkoutPlannedDateKey(workout: Workout, weekStart: Date) {
  if (!isRecurringWorkout(workout)) {
    return null
  }

  const displayIndex = DISPLAY_WEEKDAY_ORDER.indexOf(workout.scheduledDay)

  if (displayIndex < 0) {
    return null
  }

  return getDateKey(addDays(weekStart, displayIndex))
}

function getLogPlannedDateKey(log: WorkoutLog) {
  if (log.plannedDate) {
    return getDateKey(log.plannedDate)
  }

  if (isRecurringWorkout(log.workout)) {
    const startedDay = startOfDay(log.startedAt)
    const dayOffset = (startedDay.getDay() - log.workout.scheduledDay + 7) % 7
    return getDateKey(addDays(startedDay, -dayOffset))
  }

  if (log.workout.scheduledDate) {
    return getDateKey(log.workout.scheduledDate)
  }

  return getDateKey(log.startedAt)
}

function getDurationLabel(workout: Workout | null, log: WorkoutLog | null) {
  if (log?.completedAt) {
    return `${Math.max(1, differenceInMinutes(log.completedAt, log.startedAt))}m`
  }

  if (log) {
    return `${Math.max(1, differenceInMinutes(new Date(), log.startedAt))}m so far`
  }

  if (workout?.duration) {
    return `${workout.duration}m`
  }

  return undefined
}

function formatWeekRangeLabel(weekStart: Date) {
  const weekEnd = addDays(weekStart, 6)
  return `${format(weekStart, "MMM d")} - ${format(weekEnd, weekStart.getMonth() === weekEnd.getMonth() ? "d" : "MMM d")}`
}

function getRoutineTag(workout: Workout | null) {
  if (!workout) {
    return "full"
  }

  if (workout.kind === "full_body") {
    return "full"
  }

  if (workout.kind && workout.kind !== "other" && workout.kind !== "cardio") {
    return workout.kind
  }

  const muscleGroups = workout.exercises.map((exercise) => exercise.exercise.muscleGroup.toLowerCase())

  if (muscleGroups.some((group) => group.includes("leg"))) return "legs"
  if (muscleGroups.some((group) => group.includes("back"))) return "pull"
  if (muscleGroups.some((group) => group.includes("chest") || group.includes("shoulder"))) return "push"

  return workout.kind === "cardio" ? "cardio" : "full"
}

function getRoutineTagForLibrary(workout: Workout, index: number): RoutineTag {
  const tag = getRoutineTag(workout)

  if (tag === "push" || tag === "pull" || tag === "legs" || tag === "full") {
    return tag
  }

  const normalizedName = workout.name.toLowerCase()

  if (normalizedName.includes("push")) return "push"
  if (normalizedName.includes("pull")) return "pull"
  if (normalizedName.includes("leg")) return "legs"
  if (normalizedName.includes("upper")) return "upper"
  if (normalizedName.includes("lower")) return "lower"
  if (normalizedName.includes("full")) return "full"

  return ROUTINE_TAGS[index % ROUTINE_TAGS.length]
}

function mapWorkoutExerciseToRoutineExercise(workoutExercise: Workout["exercises"][number]): RoutineExercise {
  return {
    fallbackEquipment: workoutExercise.variation.equipment,
    fallbackExerciseName: workoutExercise.exercise.name,
    fallbackIsDefault: workoutExercise.variation.isDefault,
    fallbackMuscleGroup: workoutExercise.exercise.muscleGroup,
    fallbackVariationName: workoutExercise.variation.name,
    id: workoutExercise.id || createDraftId(),
    notes: workoutExercise.notes ?? "",
    reps: formatRepTarget({
      reps: workoutExercise.sets[0]?.targetReps ?? 1,
      repsMin: workoutExercise.sets[0]?.targetRepsMin,
    }),
    rir: workoutExercise.sets[0]?.rir != null ? String(workoutExercise.sets[0].rir) : "",
    restTime: workoutExercise.restTime != null ? String(workoutExercise.restTime) : "",
    sets: workoutExercise.sets.length || 1,
    variationId: workoutExercise.variation.id,
    weight: workoutExercise.sets[0]?.weight != null ? String(workoutExercise.sets[0].weight) : "",
  }
}

function mapWorkoutToRoutine(workout: Workout, index: number): Routine {
  return {
    exercises: workout.exercises.map(mapWorkoutExerciseToRoutineExercise),
    id: workout.id || createDraftId(),
    name: workout.name || `Routine ${index + 1}`,
    tag: getRoutineTagForLibrary(workout, index),
  }
}

function getTagColor(tag: string) {
  if (tag === "cardio") return "var(--chart-5)"
  return (TAG_DOT_COLOR as Record<string, string>)[tag] ?? "var(--muted-foreground)"
}

function getStatusBadge(entry: ScheduleEntry, messages: AppMessages) {
  if (entry.isCompleted) {
    return { className: "bg-ok-soft text-success-text", label: messages.schedule.done }
  }

  if (entry.isToday) {
    return { className: "bg-primary-soft text-primary", label: messages.schedule.todayLabel }
  }

  if (entry.isCatchUp) {
    return { className: "bg-warn-soft text-warning-text", label: messages.schedule.catchUpLabel }
  }

  if (entry.isMissed) {
    return { className: "bg-warn-soft text-warning-text", label: messages.schedule.missedLabel }
  }

  return null
}

/**
 * The workouts that actually belong to an arbitrary week.
 *
 * The server only ever ships the CURRENT week's program sessions, so projecting
 * that same list onto every week the user browses to is wrong twice over: it
 * keeps a finished program alive forever, and it shows this week's plan under
 * next week's dates. This rebuilds the week from each program's own schedule.
 *
 * Personal routines are deliberately exempt. They live in a synthetic one-week
 * program created by `createPersonalWorkoutForTrainee`, recur indefinitely, and
 * must keep appearing on every week ΓÇö treating them like a one-week program
 * would make them vanish everywhere but the week they were created.
 */
function buildWorkoutsForWeek({
  currentWeekWorkouts,
  programDetailsById,
  programs,
  weekStart,
}: {
  currentWeekWorkouts: Workout[]
  programDetailsById: Record<string, CoachProgram | null>
  programs: TraineeProgram[]
  weekStart: Date
}): Workout[] {
  const multiWeekById = new Map(programs.filter((program) => program.duration > 1).map((program) => [program.id, program]))

  // Dated one-offs are pinned to real dates, and personal routines recur with no
  // end, so both carry over from the current week's payload untouched.
  const carriedOver = currentWeekWorkouts.filter(
    (workout) => Boolean(workout.scheduledDate) || !workout.programId || !multiWeekById.has(workout.programId),
  )

  const fromPrograms = Array.from(multiWeekById.values()).flatMap((program) => {
    const placement = resolveProgramWeekForWeekStart(program.assignedAt, program.duration, weekStart)

    if (placement?.kind !== "active") {
      return []
    }

    const detail = programDetailsById[program.id]

    if (!detail) {
      return []
    }

    const recurring = detail.workouts.filter((workout) => !workout.scheduledDate)
    const authoredWeeks = Array.from(new Set(recurring.map((workout) => workout.weekIndex ?? 0)))
    const effectiveWeekIndex = resolveEffectiveWeekIndex(authoredWeeks, placement.weekIndex)

    if (effectiveWeekIndex == null) {
      return []
    }

    return recurring.filter((workout) => (workout.weekIndex ?? 0) === effectiveWeekIndex)
  })

  return [...carriedOver, ...fromPrograms]
}

// Sequential weekly schedule: completed sessions show on the day they were actually
// trained; days with no session are simply empty (never "missed"). Each uncompleted
// recurring session is laid out, in program order, on the earliest free day at or after
// both today and its coach-assigned weekday ΓÇö an on-track week keeps the coach's layout
// (rest days included), a behind week slides the rest forward. Mirrors the backend builder.
function buildWeekEntries({
  logs,
  optimisticScheduleByDate,
  weekStart,
  workouts,
}: {
  logs: WorkoutLog[]
  optimisticScheduleByDate: Record<string, Workout | null>
  weekStart: Date
  workouts: Workout[]
}): ScheduleEntry[] {
  const todayKey = getDateKey(startOfDay(new Date()))
  const weekStartKey = getDateKey(weekStart)
  const weekEndKey = getDateKey(addDays(weekStart, 7))
  const weekLogs = logs.filter((log) => {
    const key = getDateKey(log.startedAt)
    return key >= weekStartKey && key < weekEndKey
  })

  const cells = DISPLAY_WEEKDAY_ORDER.map((weekday, displayIndex) => {
    const date = addDays(weekStart, displayIndex)
    return { date, dateKey: getDateKey(date), weekday }
  })

  const todayIndex = (() => {
    const found = cells.findIndex((cell) => cell.dateKey === todayKey)
    if (found >= 0) return found
    return todayKey < weekStartKey ? -1 : cells.length
  })()

  const logByDay = new Map<string, WorkoutLog>()
  for (const log of weekLogs) {
    const key = getDateKey(log.startedAt)
    if (!logByDay.has(key)) {
      logByDay.set(key, log)
    }
  }
  const completedOccurrenceKeys = new Set<string>()
  const completedWorkoutMatchKeysForWeek = new Set<string>()
  const coachUpdatedWorkoutMatchKeys = new Set<string>()
  workouts
    .filter((workout) => workout.hasCoachUpdate)
    .forEach((workout) => getWorkoutCompletionMatchKeys(workout).forEach((key) => coachUpdatedWorkoutMatchKeys.add(key)))

  for (const log of weekLogs) {
    const plannedDateKey = getLogPlannedDateKey(log)

    if (plannedDateKey >= weekStartKey && plannedDateKey < weekEndKey) {
      completedOccurrenceKeys.add(getScheduleOccurrenceKey(log.workout.id, plannedDateKey))
    }
    // A workout started in this week counts as this week's completion for its
    // recurring signature, even when plannedDate spilled into a previous week
    // (catch-up sessions) ΓÇö prevents the same recurring session from also being
    // rolled forward onto a later day this week.
    getWorkoutCompletionMatchKeys(log.workout).forEach((key) => completedWorkoutMatchKeysForWeek.add(key))
  }

  // One-off workouts pinned to a date stay on that date; optimistic edits override.
  const oneOffByDay = new Map<string, Workout>()
  for (const workout of workouts) {
    if (workout.scheduledDate) {
      oneOffByDay.set(getDateKey(workout.scheduledDate), workout)
    }
  }
  for (const [dateKey, workout] of Object.entries(optimisticScheduleByDate)) {
    if (workout) {
      oneOffByDay.set(dateKey, workout)
    } else {
      oneOffByDay.delete(dateKey)
    }
  }

  const remaining = workouts
    .filter((workout) => {
      const plannedDateKey = getRecurringWorkoutPlannedDateKey(workout, weekStart)

      return Boolean(
        plannedDateKey &&
          !completedOccurrenceKeys.has(getScheduleOccurrenceKey(workout.id, plannedDateKey)) &&
          !getWorkoutCompletionMatchKeys(workout).some((key) => completedWorkoutMatchKeysForWeek.has(key)),
      )
    })
    .sort((left, right) => DISPLAY_WEEKDAY_ORDER.indexOf(left.scheduledDay as number) - DISPLAY_WEEKDAY_ORDER.indexOf(right.scheduledDay as number))

  const occupied = cells.map((cell) => logByDay.has(cell.dateKey) || oneOffByDay.has(cell.dateKey))
  const assigned = new Array<Workout | null>(cells.length).fill(null)

  for (const session of remaining) {
    const schedIndex = DISPLAY_WEEKDAY_ORDER.indexOf(session.scheduledDay as number)
    const start = Math.max(0, todayIndex < 0 ? schedIndex : Math.max(todayIndex, schedIndex))
    for (let i = start; i < cells.length; i += 1) {
      if (!occupied[i]) {
        occupied[i] = true
        assigned[i] = session
        break
      }
    }
  }

  return cells.map((cell, index) => {
    const isPast = cell.dateKey < todayKey
    const dayIsToday = cell.dateKey === todayKey
    const log = logByDay.get(cell.dateKey) ?? null

    if (log) {
      const logHasCoachUpdate = getWorkoutCompletionMatchKeys(log.workout).some((key) => coachUpdatedWorkoutMatchKeys.has(key))
      const entryWorkout = logHasCoachUpdate ? { ...log.workout, hasCoachUpdate: true } : log.workout

      return {
        date: cell.date,
        durationLabel: getDurationLabel(entryWorkout, log),
        isCatchUp: false,
        isCompleted: true,
        isMissed: false,
        isRolledOver: false,
        isToday: dayIsToday,
        log,
        source: entryWorkout.isPersonal ? "self" : "coach",
        weekday: cell.weekday,
        workout: entryWorkout,
      } satisfies ScheduleEntry
    }

    const oneOff = oneOffByDay.get(cell.dateKey) ?? null
    if (oneOff) {
      return {
        date: cell.date,
        durationLabel: getDurationLabel(oneOff, null),
        isCatchUp: false,
        isCompleted: false,
        isMissed: isPast,
        isRolledOver: false,
        isToday: dayIsToday,
        log: null,
        source: oneOff.isPersonal ? "self" : "coach",
        weekday: cell.weekday,
        workout: oneOff,
      } satisfies ScheduleEntry
    }

    const placed = assigned[index]
    const schedIndex = placed && typeof placed.scheduledDay === "number" ? DISPLAY_WEEKDAY_ORDER.indexOf(placed.scheduledDay) : -1

    return {
      date: cell.date,
      durationLabel: getDurationLabel(placed, null),
      isCatchUp: Boolean(placed) && todayIndex >= 0 && schedIndex < todayIndex,
      isCompleted: false,
      isMissed: false,
      isRolledOver: false,
      isToday: dayIsToday,
      log: null,
      source: placed?.isPersonal ? "self" : "coach",
      weekday: cell.weekday,
      workout: placed,
    } satisfies ScheduleEntry
  })
}

