}))

vi.mock("@/components/providers/locale-provider", () => ({
  useLocale: () => ({
    messages: {
      workoutPage: {
        exerciseAnimationAlt: (name: string) => `${name} animation`,
        exerciseMediaUnavailable: "Media unavailable",
        playExerciseAnimation: "Play animation",
      },
    },
  }),
}))

const media = {
  animationUrl: "https://project.supabase.co/animation.gif",
  height: 180 as const,
  thumbnailUrl: "https://project.supabase.co/thumbnail.jpg",
  width: 180 as const,
}

function mockReducedMotion(matches: boolean) {
  Object.defineProperty(window, "matchMedia", {
    configurable: true,
    value: vi.fn(() => ({
      addEventListener: vi.fn(),
      matches,
      media: "(prefers-reduced-motion: reduce)",
      removeEventListener: vi.fn(),
    })),
  })
}

describe("ExerciseAnimation", () => {
  afterEach(() => {
    cleanup()
    vi.restoreAllMocks()
  })

  it("autoplays the GIF and shows attribution when motion is allowed", () => {
    mockReducedMotion(false)
    render(<ExerciseAnimation exerciseName="Row" media={media} />)
    expect(screen.getByRole("img")).toHaveAttribute("src", media.animationUrl)
    expect(screen.getByRole("link", { name: "┬⌐ Gym visual" })).toBeVisible()
  })

  it("keeps the thumbnail for reduced motion until explicit playback", () => {
    mockReducedMotion(true)
    render(<ExerciseAnimation exerciseName="Row" media={media} />)
    expect(screen.getByRole("img")).toHaveAttribute("src", media.thumbnailUrl)
    fireEvent.click(screen.getByRole("button", { name: "Play animation" }))
    expect(screen.getByRole("img")).toHaveAttribute("src", media.animationUrl)
  })

  it("hides broken media while preserving an accessible unavailable status", () => {
    mockReducedMotion(false)
    render(<ExerciseAnimation exerciseName="Row" media={media} />)
    fireEvent.error(screen.getByRole("img"))
    expect(screen.queryByRole("img")).not.toBeInTheDocument()
    expect(screen.getByRole("status")).toHaveTextContent("Media unavailable")
  })
})

"use client"

import { Plus, SkipForward } from "lucide-react"
import { useEffect, useRef, useState } from "react"

import { useLocale } from "@/components/providers/locale-provider"
import { cn } from "@/lib/utils"

export type RestEvent = {
  duration?: number
  exercise: string
  set: { id: string; kg: number | null; reps: number | null }
} | null

interface RestTimerProps {
  event: RestEvent
  onDismiss: () => void
  defaultDuration?: number
}

export function RestTimer({ event, onDismiss, defaultDuration = 90 }: RestTimerProps) {
  const { messages } = useLocale()
  const [remaining, setRemaining] = useState(defaultDuration)
  const [visible, setVisible] = useState(true)
  const startedRef = useRef(Date.now())
  const totalRef = useRef(defaultDuration)
  const intervalRef = useRef<ReturnType<typeof setInterval> | null>(null)

  // Reset and start whenever a new event fires
  useEffect(() => {
    if (!event) return

    const duration = event.duration ?? defaultDuration
    totalRef.current = duration
    startedRef.current = Date.now()
    setRemaining(duration)
    setVisible(true)

    if (intervalRef.current) clearInterval(intervalRef.current)

    intervalRef.current = setInterval(() => {
      const elapsed = (Date.now() - startedRef.current) / 1000
      const r = Math.max(0, totalRef.current - elapsed)
      setRemaining(r)

      if (r <= 0) {
        if (intervalRef.current) clearInterval(intervalRef.current)
        setTimeout(() => {
          setVisible(false)
          setTimeout(onDismiss, 400)
        }, 0)
      }
    }, 100)

    return () => {
      if (intervalRef.current) clearInterval(intervalRef.current)
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [event?.exercise, event?.set?.id])

  const handleAddTime = () => {
    totalRef.current = remaining + 30
    startedRef.current = Date.now()
    setRemaining((r) => r + 30)
  }

  const handleSkip = () => {
    if (intervalRef.current) clearInterval(intervalRef.current)
    setVisible(false)
    setTimeout(onDismiss, 400)
  }

  const mins = Math.floor(remaining / 60)
  const secs = Math.floor(remaining % 60)
  const pct = totalRef.current > 0 ? (remaining / totalRef.current) * 100 : 0

  if (!event) return null

  return (
    <div
      className={cn(
        "workout-floating-chip fixed z-50 pointer-events-auto",
        // Desktop: offset left by sidebar width (280px)
        "bottom-[calc(0.75rem+env(safe-area-inset-bottom))] left-1/2 w-[calc(100%-2rem)] max-w-[390px] -translate-x-1/2",
        "md:left-[280px] md:right-10 md:w-auto md:max-w-none md:translate-x-0 md:bottom-6",
        "transition-opacity duration-[400ms]",
        visible ? "opacity-100" : "opacity-0",
      )}
    >
      <div
        className={cn(
          "flex items-center gap-3 md:gap-5",
          "rounded-xl border border-border",
          "bg-background/90 backdrop-blur-xl",
          "px-3 py-3 md:px-5 md:py-[14px]",
          "shadow-[var(--glass-shadow)]",
          "flex-wrap md:flex-nowrap",
        )}
      >
        {/* Left: label + countdown */}
        <div className="min-w-[90px] md:min-w-[110px] shrink-0">
          <div className="font-mono text-micro uppercase tracking-[0.08em] text-muted-foreground mb-[2px]">
            {messages.workoutPage.rest}
          </div>
          <div
            className="font-mono text-3xl md:text-4xl font-semibold text-primary leading-none"
          >
            {String(mins)}:{String(secs).padStart(2, "0")}
          </div>
        </div>

        {/* Middle: progress bar + caption */}
        <div
          className={cn(
            "flex-1 min-w-0",
            // On mobile, force to its own row after left+right sections
            "order-3 md:order-none w-full md:w-auto",
          )}
        >
          {/* Progress track */}
          <div className="h-1 rounded-full bg-border overflow-hidden">
            <div
              className="h-full rounded-full bg-primary transition-[width] duration-100 ease-linear"
              style={{ width: `${pct}%` }}
            />
          </div>
          {/* Caption */}
          <p className="mt-2 text-xs text-muted-foreground overflow-hidden text-ellipsis whitespace-nowrap">
            {messages.workoutPage.after}{" "}
            <span className="text-foreground">
              {event.exercise}
            </span>
            {event.set && (
              <>
                {" ┬╖ "}
                <span className="font-mono">
                  {event.set.kg ?? "ΓÇö"} kg ├ù {event.set.reps ?? "ΓÇö"}
                </span>
              </>
            )}
          </p>
        </div>

        {/* Right: action buttons */}
        <div className="flex items-center gap-2 ml-auto shrink-0">
          <button
            onClick={handleAddTime}
            aria-label={messages.workoutPage.add30Seconds}
            className={cn(
              "flex items-center gap-1 rounded-md border border-border",
              "px-3 py-1.5 text-sm font-medium text-foreground",
              "bg-transparent hover:bg-muted transition-colors duration-150",
            )}
          >
            <Plus className="h-3.5 w-3.5" />
            30 s
          </button>
          <button
            onClick={handleSkip}
            aria-label={messages.workoutPage.skipRest}
            className={cn(
              "flex items-center gap-1 rounded-md",
              "px-3 py-1.5 text-sm font-medium",
              "bg-transparent text-destructive-text hover:bg-destructive-soft transition-colors duration-150",
            )}
          >
            <SkipForward className="h-3.5 w-3.5" />
            {messages.workoutPage.skip}
          </button>
        </div>
      </div>
    </div>
  )
}

"use client"

import { Play, X } from "lucide-react"
import { usePathname, useRouter } from "next/navigation"
import { useCallback, useEffect, useState } from "react"

import { useLocale } from "@/components/providers/locale-provider"
import { cn } from "@/lib/utils"
import {
  type ActiveWorkoutSession,
  WORKOUT_SESSION_STORAGE_PREFIX,
  clearStoredWorkoutSession,
  scanActiveSessions,
} from "@/lib/workout/session-storage"

const START_PATH_PATTERN = /^\/workout\/[^/]+\/start(\/|$)/

function formatElapsed(startedAt: string, now: number): string {
  const startMs = Date.parse(startedAt)
  if (!Number.isFinite(startMs)) return "0:00"
  const elapsed = Math.max(0, Math.floor((now - startMs) / 1000))
  const hours = Math.floor(elapsed / 3600)
  const mins = Math.floor((elapsed % 3600) / 60)
  const secs = elapsed % 60
  if (hours > 0) {
    return `${hours}:${String(mins).padStart(2, "0")}:${String(secs).padStart(2, "0")}`
  }
  return `${mins}:${String(secs).padStart(2, "0")}`
}

function formatStartedAgo(startedAt: string, now: number): string {
  const startMs = Date.parse(startedAt)
  if (!Number.isFinite(startMs)) return ""
  const seconds = Math.max(0, Math.floor((now - startMs) / 1000))
  if (seconds < 60) return `${seconds}s`
  const minutes = Math.floor(seconds / 60)
  if (minutes < 60) return `${minutes}m`
  const hours = Math.floor(minutes / 60)
  const remMins = minutes % 60
  return remMins > 0 ? `${hours}h ${remMins}m` : `${hours}h`
}

export function ResumeWorkoutCard() {
  const { messages } = useLocale()
  const router = useRouter()
  const pathname = usePathname()
  const [session, setSession] = useState<ActiveWorkoutSession | null>(null)
  const [now, setNow] = useState(() => Date.now())
  const [visible, setVisible] = useState(false)

  const refresh = useCallback(() => {
    const sessions = scanActiveSessions()
    setSession(sessions[0] ?? null)
  }, [])

  // Rescan on mount and whenever the route changes (e.g. after leaving /start)
  useEffect(() => {
    refresh()
  }, [pathname, refresh])

  // Cross-tab sync: rescan when any workout-session key changes
  useEffect(() => {
    const onStorage = (event: StorageEvent) => {
      if (event.key === null || event.key.startsWith(`${WORKOUT_SESSION_STORAGE_PREFIX}:`)) {
        refresh()
      }
    }
    window.addEventListener("storage", onStorage)
    return () => window.removeEventListener("storage", onStorage)
  }, [refresh])

  const onStartPage = pathname ? START_PATH_PATTERN.test(pathname) : false
  const shouldShow = !!session && !onStartPage

  // Drive the fade transition
  useEffect(() => {
    if (!shouldShow) {
      setVisible(false)
      return
    }
    const id = requestAnimationFrame(() => setVisible(true))
    return () => cancelAnimationFrame(id)
  }, [shouldShow])

  // Tick the elapsed timer every second while visible
  useEffect(() => {
    if (!shouldShow) return
    const id = setInterval(() => setNow(Date.now()), 1000)
    return () => clearInterval(id)
  }, [shouldShow])

  if (!session || onStartPage) return null

  const handleResume = () => {
    router.push(`/workout/${session.workoutId}/start`, { scroll: true })
  }

  const handleDiscard = () => {
    clearStoredWorkoutSession(session.workoutId)
    setVisible(false)
    setSession(null)
  }

  const name = session.workoutName?.trim() || messages.workoutPage.workoutInProgress
  const elapsed = formatElapsed(session.startedAt, now)
  const startedAgo = formatStartedAgo(session.startedAt, now)

  return (
    <div
      className={cn(
        "workout-floating-chip fixed z-40 pointer-events-auto",
        "bottom-[calc(4.75rem+env(safe-area-inset-bottom))] left-1/2 w-[calc(100%-2rem)] max-w-[390px] -translate-x-1/2",
        "md:left-[280px] md:right-24 md:w-auto md:max-w-none md:translate-x-0 md:bottom-6",
        "transition-opacity duration-[400ms]",
        visible ? "opacity-100" : "opacity-0",
      )}
    >
      <div
        className={cn(
          "flex items-center gap-2 md:gap-5",
          "rounded-3xl border border-border md:rounded-xl",
          "bg-background/90 backdrop-blur-xl",
          "px-2.5 py-2 md:px-5 md:py-[14px]",
          "shadow-[var(--glass-shadow)]",
        )}
      >
        {/* Left: label + workout name */}
        <div className="min-w-0 flex-1 md:flex-none md:min-w-[160px] md:max-w-[240px]">
          <div className="mb-0.5 flex items-center gap-1.5 font-mono text-micro uppercase tracking-[0.08em] text-muted-foreground md:text-micro">
            <span className="h-1.5 w-1.5 animate-pulse rounded-full bg-success" />
            {messages.workoutPage.inProgress}
          </div>
          <div className="truncate text-sm font-semibold leading-tight text-foreground md:text-base">
            {name}
          </div>
        </div>

        {/* Middle: elapsed + caption */}
        <div className="shrink-0 text-right md:min-w-0 md:flex-1 md:text-left">
          <div
            className="font-mono text-lg font-semibold leading-none text-primary md:text-2xl"
          >
            {elapsed}
          </div>
          <p className="mt-1 whitespace-nowrap text-micro text-muted-foreground md:mt-1.5 md:overflow-hidden md:text-ellipsis md:text-xs">
            <span className="font-mono">
              {messages.workoutPage.setsProgress(session.completedSets, session.totalSets)}
            </span>
            {startedAgo && (
              <span className="hidden md:inline">
                {" ┬╖ "}
                {messages.workoutPage.startedAgo(startedAgo)}
              </span>
            )}
          </p>
        </div>

        {/* Right: actions */}
        <div className="ml-0.5 flex shrink-0 items-center gap-1.5 md:ml-auto md:gap-2">
          <button
            onClick={handleResume}
            aria-label={messages.workoutPage.resume}
            className={cn(
              "flex h-9 items-center gap-1 rounded-full px-2.5 text-xs font-medium md:h-auto md:rounded-md md:px-3 md:py-1.5 md:text-sm",
              "bg-primary text-primary-foreground hover:bg-primary/90 transition-colors duration-150",
            )}
          >
            <Play className="h-3.5 w-3.5" fill="currentColor" />
            {messages.workoutPage.resume}
          </button>
          <button
            onClick={handleDiscard}
            aria-label={messages.workoutPage.discard}
            className={cn(
              "flex h-9 w-9 items-center justify-center rounded-full text-sm font-medium md:h-auto md:w-auto md:rounded-md md:px-3 md:py-1.5",
              "bg-transparent text-destructive-text hover:bg-destructive-soft transition-colors duration-150",
            )}
          >
            <X className="h-3.5 w-3.5" />
            <span className="sr-only md:not-sr-only">{messages.workoutPage.discard}</span>
          </button>
        </div>
      </div>
    </div>
  )
}

