}

function getRoutineTagLabel(tag: RoutineTag, messages: ReturnType<typeof useLocale>["messages"]) {
  const labels: Record<RoutineTag, string> = {
    full: messages.workoutPage.tagFull,
    legs: messages.workoutPage.tagLegs,
    lower: messages.workoutPage.tagLower,
    pull: messages.workoutPage.tagPull,
    push: messages.workoutPage.tagPush,
    upper: messages.workoutPage.tagUpper,
  }
  return labels[tag]
}

function draftId() {
  return `draft-${Date.now()}-${Math.random().toString(36).slice(2)}`
}

function inferTag(workout: Workout): RoutineTag {
  const kind = workout.kind
  if (kind === "push" || kind === "pull" || kind === "legs") return kind
  if (kind === "full_body") return "full"
  const name = workout.name.toLowerCase()
  if (name.includes("upper")) return "upper"
  if (name.includes("lower")) return "lower"
  if (name.includes("push"))  return "push"
  if (name.includes("pull"))  return "pull"
  if (name.includes("leg"))   return "legs"
  return "full"
}

function toDraft(exercise: Workout["exercises"][number]): RoutineExerciseDraft {
  const set0 = exercise.sets[0]
  return {
    id: draftId(),
    variationId: exercise.variation.id,
    displayName: exercise.exercise.name,
    muscleGroup: exercise.exercise.muscleGroup,
    activityType: exercise.variation.activityType,
    primaryMuscles: exercise.variation.primaryMuscles,
    secondaryMuscles: exercise.variation.secondaryMuscles,
    equipment: exercise.variation.equipment,
    sets: exercise.sets.length,
    reps: formatRepTarget({ reps: set0?.targetReps ?? 10, repsMin: set0?.targetRepsMin }),
    weight: set0?.weight != null ? String(set0.weight) : "",
    rir: set0?.rir != null ? String(set0.rir) : "",
    restTime: exercise.restTime != null ? String(exercise.restTime) : "",
    notes: exercise.notes ?? "",
  }
}

// ΓöÇΓöÇΓöÇ FieldNum ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

const fieldInputClass = cn(
  "w-full rounded border border-border bg-background px-2 py-1.5 text-center font-mono text-sm text-foreground",
  "focus:outline-none focus:ring-1 focus:ring-ring",
  "[appearance:textfield] [&::-webkit-inner-spin-button]:appearance-none [&::-webkit-outer-spin-button]:appearance-none",
)

function FieldNum({
  label,
  value,
  onChange,
  allowDecimals,
  allowRange,
  placeholder,
}: {
  label: string
  value: string
  onChange: (v: string) => void
  allowDecimals?: boolean
  allowRange?: boolean
  placeholder?: string
}) {
  const inputType = allowDecimals ? "number" : "text"
  // allowRange fields (reps / RIR) accept values like "8-12" ΓÇö mobile numeric
  // keypads have no "-" key, so fall back to the full text keyboard for those.
  const inputMode = allowRange ? "text" : allowDecimals ? "decimal" : "numeric"
  return (
    <div className="flex flex-col gap-1">
      <span className="font-mono text-micro uppercase tracking-[0.08em] text-muted-foreground">
        {label}
      </span>
      <input
        type={inputType}
        inputMode={inputMode}
        value={value}
        step={allowDecimals ? "0.5" : "1"}
        min="0"
        placeholder={placeholder ?? ""}
        onChange={(e) => onChange(e.target.value)}
        className={fieldInputClass}
      />
    </div>
  )
}


/**
 * Turns a routine draft into the workout payload the API expects. Shared with
 * the program editor so a session added to a program is normalized exactly the
 * same way as one saved from this dialog.
 *
 * Throws with a localized message on unparseable reps or an empty routine.
 */
export function buildRoutineWorkoutPayload(
  draft: { exercises: RoutineExerciseDraft[]; name: string; tag: RoutineTag },
  messages: AppMessages,
) {
  const normalizedExercises = draft.exercises
    .filter((ex) => ex.variationId)
    .map((ex, i) => {
      const repTarget = parseRepTargetText(ex.reps)
      if (!repTarget) throw new Error(messages.workoutPage.invalidRepsAtExercise(i + 1))
      const parsedWeight = Number(ex.weight)
      const parsedRir = Number(ex.rir)
      const parsedRest = Number(ex.restTime)
      return {
        notes: ex.notes?.trim() || undefined,
        reps: repTarget.reps,
        repsMin: repTarget.repsMin,
        rir: ex.rir.trim() && Number.isFinite(parsedRir) ? Math.max(0, Math.round(parsedRir)) : undefined,
        restTime: ex.restTime?.trim() && Number.isFinite(parsedRest) ? Math.max(0, Math.round(parsedRest)) : undefined,
        variationId: ex.variationId,
        sets: Math.max(1, Number(ex.sets) || 1),
        weight: ex.weight.trim() && Number.isFinite(parsedWeight) ? Math.max(0, parsedWeight) : undefined,
      }
    })

  if (normalizedExercises.length === 0) {
    throw new Error(messages.workoutPage.addAtLeastOneExercise)
  }

  return {
    exercises: normalizedExercises,
    kind: draft.tag === "upper" || draft.tag === "lower" || draft.tag === "full" ? "full_body" : draft.tag,
    name: draft.name,
  }
}

// ΓöÇΓöÇΓöÇ RoutineBuilderDialog ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ

export function RoutineBuilderDialog({
  trigger,
  workoutToEdit,
  onWorkoutSaved,
  open: controlledOpen,
  onOpenChange,
  draftToEdit,
  onSaveDraft,
}: RoutineBuilderDialogProps) {
  const createWorkoutMutation = useCreateWorkout()
  const updateWorkoutMutation = useUpdateWorkout()
  const { isLoading: authLoading, session } = useAuth()
  const { messages } = useLocale()
  const isEditing = Boolean(workoutToEdit) || Boolean(draftToEdit?.id)
  const isControlled = controlledOpen !== undefined

  const [internalOpen, setInternalOpen] = useState(false)
  const open = isControlled ? controlledOpen! : internalOpen
  const setOpen = (v: boolean) => {
    if (isControlled) onOpenChange?.(v)
    else setInternalOpen(v)
  }

  const [name, setName] = useState("")
  const [tag, setTag] = useState<RoutineTag>("push")
  const [exercises, setExercises] = useState<RoutineExerciseDraft[]>([])
  // "add" = add new exercise; exerciseId = swap that exercise; null = closed
  const [pickerTarget, setPickerTarget] = useState<string | "add" | null>(null)
  const libraryQuery = useExercises(undefined, undefined, Boolean(pickerTarget))
  const library = libraryQuery.data ?? []
  const loadingLibrary = libraryQuery.isFetching
  const [isSaving, setIsSaving] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const totalSets = exercises.reduce((acc, ex) => acc + (Number(ex.sets) || 0), 0)
  const canSave = name.trim().length > 0 && exercises.length > 0 && !isSaving
  // Recomputed straight from draft state, so the figure tracks every add and
  // remove ΓÇö that live feedback is the point of showing it in the editor.
  const muscleHighlights = buildMuscleProfileHighlights(
    exercises,
    "var(--primary)",
    "color-mix(in oklab, var(--primary) 45%, var(--body-fill))",
  )

  // ΓöÇΓöÇ Reset form on open/close ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const resetForm = () => {
    if (draftToEdit) {
      setName(draftToEdit.name)
      setTag(draftToEdit.tag)
      setExercises(draftToEdit.exercises)
    } else if (workoutToEdit) {
      setName(workoutToEdit.name)
      setTag(inferTag(workoutToEdit))
      setExercises(workoutToEdit.exercises.map(toDraft))
    } else {
      setName("")
      setTag("push")
      setExercises([])
    }
    setError(null)
  }

  useEffect(() => {
    if (open) resetForm()
  }, [open])



  // ΓöÇΓöÇ Exercise handlers ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const pickExercise = (ex: ExerciseVariationOption) => {
    if (pickerTarget === "add") {
      // Add new exercise at the end
      setExercises((prev) => [
        ...prev,
        {
          id: draftId(),
          variationId: ex.id,
          displayName: ex.exerciseName,
          muscleGroup: ex.muscleGroup,
          activityType: ex.activityType,
          primaryMuscles: ex.primaryMuscles,
          secondaryMuscles: ex.secondaryMuscles,
          equipment: ex.equipment,
          sets: 3,
          reps: "10",
          weight: "",
          rir: "",
          restTime: "",
          notes: "",
        },
      ])
    } else if (pickerTarget) {
      // Swap in-place ΓÇö keep sets/reps/weight/rir, replace identity
      setExercises((prev) =>
        prev.map((item) =>
          item.id === pickerTarget
            ? {
                ...item,
                variationId: ex.id,
                displayName: ex.exerciseName,
                muscleGroup: ex.muscleGroup,
                activityType: ex.activityType,
                primaryMuscles: ex.primaryMuscles,
                secondaryMuscles: ex.secondaryMuscles,
                equipment: ex.equipment,
              }
            : item,
        ),
      )
    }
    setPickerTarget(null)
  }

  const updateExercise = (id: string, patch: Partial<RoutineExerciseDraft>) => {
    setExercises((prev) => {
      const isFirst = prev.length > 0 && prev[0].id === id
      if (isFirst && patch.rir !== undefined) {
        return prev.map((ex) => ({ ...ex, rir: patch.rir ?? ex.rir, ...(ex.id === id ? patch : {}) }))
      }
      return prev.map((ex) => (ex.id === id ? { ...ex, ...patch } : ex))
    })
  }

  const removeExercise = (id: string) => {
    setExercises((prev) => prev.filter((ex) => ex.id !== id))
  }

  const moveExercise = (idx: number, dir: -1 | 1) => {
    setExercises((prev) => {
      const next = [...prev]
      const target = idx + dir
      if (target < 0 || target >= next.length) return prev
      ;[next[idx], next[target]] = [next[target], next[idx]]
      return next
    })
  }

  // ΓöÇΓöÇ Save ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  const handleSave = async () => {
    if (!canSave) return

    // Draft mode (coach): no DB save ΓÇö hand data back to caller
    if (onSaveDraft) {
      onSaveDraft({ id: draftToEdit?.id, name: name.trim(), tag, exercises })
      setOpen(false)
      return
    }

    if (!session?.access_token) return
    setIsSaving(true)
    setError(null)

    try {
      const payload = buildRoutineWorkoutPayload({ exercises, name: name.trim(), tag }, messages)

      let saved: Workout
      if (isEditing && workoutToEdit) {
        saved = await updateWorkoutMutation.mutateAsync({ workoutId: workoutToEdit.id, input: payload })
      } else {
        saved = await createWorkoutMutation.mutateAsync(payload)
      }

      onWorkoutSaved?.(saved, workoutToEdit)
      setOpen(false)
    } catch (err) {
      setError(err instanceof Error ? err.message : messages.workoutPage.saveRoutineError)
    } finally {
      setIsSaving(false)
    }
  }

  // ΓöÇΓöÇ Render ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ
  return (
    <Dialog open={open} onOpenChange={setOpen}>
      {/* Trigger (uncontrolled mode only) */}
      {trigger != null && (
        <DialogTrigger asChild>
          <span onClick={(e) => { if (authLoading) e.preventDefault(); }} className="contents">
            {trigger}
          </span>
        </DialogTrigger>
      )}

      <DialogContent
        showCloseButton={false}
        className="flex h-[calc(100svh-1rem)] max-h-[calc(100svh-1rem)] w-full flex-col overflow-hidden p-0 sm:h-[90svh] sm:max-h-[900px] sm:max-w-[640px] sm:rounded-xl"
      >
        <DialogHeader className="sr-only">
          <DialogTitle>{isEditing ? messages.workoutPage.editRoutineMode : messages.workoutPage.newRoutine}</DialogTitle>
          <DialogDescription>{messages.workoutPage.routineNamePlaceholder}</DialogDescription>
        </DialogHeader>

        {/* ΓöÇΓöÇ Header ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
        <div className="border-b border-border px-4 pb-[18px] pt-5 sm:px-7 sm:pt-6">
              <div className="mb-4 flex items-start justify-between">
                <div>
                  <p className="label-micro mb-1.5 text-muted-foreground">
                    {isEditing ? messages.workoutPage.editRoutineMode : messages.workoutPage.newRoutine}
                  </p>
                  <h2 className="text-2xl font-semibold leading-tight tracking-[-0.02em] text-foreground">
                    {name.trim() || messages.workoutPage.untitledRoutine}
                  </h2>
                  <p className="mt-1 font-mono text-xs text-muted-foreground">
                    {messages.workoutPage.exerciseCount(exercises.length)} ┬╖ {messages.workoutPage.setCount(totalSets)}
                  </p>
                </div>
                <div className="flex shrink-0 items-start gap-3">
                  <MuscleMapPair
                    size="sm"
                    highlights={muscleHighlights}
                    label={messages.workoutPage.muscleMapLabel}
                    className="mt-0.5"
                  />
                  <DialogClose asChild>
                    <button
                      type="button"
                      className="shrink-0 rounded-md p-1 text-muted-foreground transition-colors hover:text-foreground"
                    >
                      <X className="h-[18px] w-[18px]" />
                    </button>
                  </DialogClose>
                </div>
              </div>

              <div className="flex flex-col gap-2.5 sm:flex-row sm:items-center">
                <Input
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder={messages.workoutPage.routineNamePlaceholder}
                  className="flex-1 text-base"
                  autoFocus
                />
                <div className="flex gap-1.5 overflow-x-auto pb-0.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden">
                  {ROUTINE_TAGS.map((t) => (
                    <button
                      key={t}
                      type="button"
                      onClick={() => setTag(t)}
                      className={cn(
                        "inline-flex h-8 pointer-coarse:h-10 shrink-0 items-center gap-1.5 rounded-full border px-3 text-xs font-medium transition-colors",
                        tag === t
                          ? "border-foreground bg-foreground text-background"
                          : "border-border bg-background text-foreground hover:border-foreground/30",
                      )}
                    >
                      <span
                        className="h-1.5 w-1.5 shrink-0 rounded-full"
                        style={{ background: TAG_DOT[t] }}
                      />
                      {getRoutineTagLabel(t, messages)}
                    </button>
                  ))}
                </div>
              </div>
            </div>

            {/* ΓöÇΓöÇ Exercise list ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
            <div className="min-h-0 flex-1 overflow-y-auto overflow-x-hidden px-4 py-4 sm:px-7">
              {error && (
                <div className="mb-4 rounded-lg border border-destructive/30 bg-destructive-soft px-4 py-3 text-sm text-destructive-text">
                  {error}
                </div>
              )}

              {exercises.length === 0 && (
                <div className="mb-4 flex flex-col items-center justify-center rounded-lg border border-dashed border-border py-10 text-center text-muted-foreground">
                  <Dumbbell className="mb-2.5 h-5 w-5 opacity-50" />
                  <p className="text-sm">{messages.workoutPage.noExercisesYet}</p>
                </div>
              )}

              {exercises.map((ex, i) => (
                <div
                  key={ex.id}
                  className="mb-2.5 rounded-lg border border-border bg-background p-3.5 sm:px-[18px]"
                >
                  <div className="mb-2.5 flex items-center gap-2.5">
                    <span className="min-w-[18px] text-right font-mono text-xs font-semibold text-muted-foreground">
                      {i + 1}
                    </span>
                    <button
                      type="button"
                      title={messages.workoutPage.swapExercise}
                      onClick={() => setPickerTarget(ex.id)}
                      className="min-w-0 flex-1 rounded-lg border border-border/60 px-3 py-2 text-left transition-colors hover:border-primary/40 hover:bg-muted/50"
                    >
                      <p className="truncate text-sm font-medium text-foreground">{ex.displayName}</p>
                      <p className="mt-0.5 truncate font-mono text-micro uppercase tracking-[0.08em] text-muted-foreground">
                        {ex.muscleGroup}{ex.equipment ? ` ┬╖ ${ex.equipment}` : ""}
                        <span className="ml-1.5 text-primary/70">{messages.workoutPage.tapToSwap}</span>
                      </p>
                    </button>
                    <div className="flex items-center gap-1">
                      <button
                        type="button"
                        onClick={() => moveExercise(i, -1)}
                        disabled={i === 0}
                        className="rounded p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:opacity-30"
                      >
                        <ChevronUp className="h-3.5 w-3.5" />
                      </button>
                      <button
                        type="button"
                        onClick={() => moveExercise(i, 1)}
                        disabled={i === exercises.length - 1}
                        className="rounded p-1 text-muted-foreground transition-colors hover:bg-muted hover:text-foreground disabled:opacity-30"
                      >
                        <ChevronDown className="h-3.5 w-3.5" />
                      </button>
                      <button
                        type="button"
                        onClick={() => removeExercise(ex.id)}
                        className="rounded p-1 text-muted-foreground transition-colors hover:bg-destructive-soft hover:text-destructive-text"
                      >
                        <Trash2 className="h-3.5 w-3.5" />
                      </button>
                    </div>
                  </div>

                  <div className="grid grid-cols-5 gap-1.5 sm:gap-2">
                    <FieldNum
                      label={messages.workoutPage.set}
                      value={String(ex.sets)}
                      onChange={(v) => updateExercise(ex.id, { sets: Number(v) || 0 })}
                    />
                    <FieldNum
                      label={messages.workoutPage.reps}
                      value={ex.reps}
                      onChange={(v) => updateExercise(ex.id, { reps: v })}
                      placeholder="8-12"
                      allowRange
                    />
                    <FieldNum
                      label="kg"
                      value={ex.weight}
                      onChange={(v) => updateExercise(ex.id, { weight: v })}
                      allowDecimals
                    />
                    <FieldNum
                      label="RIR"
                      value={ex.rir}
                      onChange={(v) => updateExercise(ex.id, { rir: v })}
                      placeholder="0-4"
                      allowRange
                    />
                    <FieldNum
                      label="REST"
                      value={ex.restTime ?? ""}
                      onChange={(v) => updateExercise(ex.id, { restTime: v })}
                      placeholder="90"
                    />
                  </div>

                  <textarea
                    value={ex.notes ?? ""}
                    onChange={(e) => updateExercise(ex.id, { notes: e.target.value })}
                    placeholder={messages.workoutPage.addNote}
                    rows={1}
                    className={cn(
                      "mt-2 w-full resize-none rounded border border-border bg-background px-3 py-1.5 text-sm text-foreground placeholder:text-muted-foreground/60",
                      "focus:outline-none focus:ring-1 focus:ring-ring",
                    )}
                  />
                </div>
              ))}

              {/* Add exercise button */}
              <button
                type="button"
                onClick={() => setPickerTarget("add")}
                className={cn(
                  "mt-1.5 flex w-full items-center justify-center gap-1.5 rounded-lg",
                  "border border-dashed border-border py-3.5 text-sm font-medium text-primary",
                  "transition-colors hover:bg-muted/50",
                )}
              >
                <span className="text-base leading-none">+</span>
                {messages.workoutPage.addExercise}
              </button>
            </div>

            {/* ΓöÇΓöÇ Footer ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ */}
            <div className="flex flex-col-reverse gap-2.5 border-t border-border bg-background px-4 pb-[calc(0.75rem+env(safe-area-inset-bottom))] pt-3 sm:flex-row sm:justify-end sm:px-7 sm:pb-3">
              <DialogClose asChild>
                <Button variant="ghost" className="w-full sm:w-auto">
                  {messages.common.cancel}
                </Button>
              </DialogClose>
              <Button
                className="w-full sm:w-auto"
                onClick={() => void handleSave()}
                disabled={!canSave}
              >
                {isSaving ? messages.workoutPage.saving : isEditing ? messages.workoutPage.saveChanges : messages.workoutPage.saveRoutine}
              </Button>
            </div>
      </DialogContent>

      {/* Exercise picker sub-modal */}
      {pickerTarget && (
              <AddExerciseModal
                exercises={loadingLibrary ? [] : library}
                loading={loadingLibrary}
                currentVariationId={pickerTarget !== "add" ? exercises.find((e) => e.id === pickerTarget)?.variationId : undefined}
                existingVariationIds={
                  // When swapping: exclude the exercise being swapped so it shows as pickable
                  (pickerTarget === "add"
                    ? exercises
                    : exercises.filter((e) => e.id !== pickerTarget)
                  ).map((e) => e.variationId)
                }
                onPick={pickExercise}
                onClose={() => setPickerTarget(null)}
              />
            )}
    </Dialog>
  )
}

"use client"

import { useEffect, useState } from "react"
import { Download, Eye, Loader2 } from "lucide-react"

import { Button } from "@/components/ui/button"
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog"
import { Label } from "@/components/ui/label"
import { useLocale } from "@/components/providers/locale-provider"
import { WorkoutLogsPreview } from "@/components/workout/workout-logs-preview"
import type { PlannedSession } from "@/components/workout-export-excel"
import { formatDisplayDate } from "@/lib/fitness/date-range"
import type { BodyMetricEntry } from "@/lib/fitness/types"
import { cn } from "@/lib/utils"
import type { WorkoutLog } from "@/lib/types"

export type ExportMode = "week" | "program"

export type ResolvedExportRange = {
  from: string
  label: string
  /** When set, the Excel export splits into one "Week N" sheet per week with logs. */
  programStartDate?: string
  to: string
}

export type ExportSelection = {
  mode: ExportMode
  programId?: string
  subjectId?: string
  weekStart: string
}

export type ExportContext = ExportSelection & { range: ResolvedExportRange }

/** A selectable export subject (e.g. a trainee). Omit `subjects` for self-export. */
export type ExportSubject = {
  id: string
  /** Display text in the picker; falls back to `name`. */
  label?: string
  /** Plain name used for the export filename / "Client:" line. */
  name: string
}

export type ExportProgramOption = {
  id: string
  name: string
}

export type WorkoutExportDialogConfig = {
  defaultMode?: ExportMode
  description?: string
  dialogContentClassName?: string
  dialogOverlayClassName?: string
  exportToSheets: (context: ExportContext) => Promise<{ logCount: number; rowCount: number }>
  loadBodyMetrics?: (context: ExportContext) => Promise<BodyMetricEntry[]>
  loadLogs: (context: ExportContext) => Promise<WorkoutLog[]>
  /** Programs offered in the Program-mode picker. Omit when the program is fixed. */
  programs?: ExportProgramOption[]
  /** Resolve the date range for Program mode (Week mode is handled internally). */
  resolveProgramRange: (selection: ExportSelection) => ResolvedExportRange | { error: string }
  /**
   * Resolve the program's planned sessions (with calendar dates) for the Excel
   * export. Scheduled-but-unlogged days are then shown with blank actuals.
   */
  resolvePlannedSessions?: (selection: ExportSelection) => Promise<PlannedSession[]> | PlannedSession[]
  showProgramPicker?: boolean
  subjectPlaceholder?: string
  subjectSelectLabel?: string
  subjects?: ExportSubject[]
  title: string
  triggerLabel: string
}

// Local YYYY-MM-DD (not UTC) so week boundaries match the user's timezone.
function toLocalISODate(date: Date) {
  const year = date.getFullYear()
  const month = String(date.getMonth() + 1).padStart(2, "0")
  const day = String(date.getDate()).padStart(2, "0")
  return `${year}-${month}-${day}`
}

function getWeekStart(date: Date) {
  const next = new Date(date)
  // Snap back to Monday. getDay() is 0 (Sun)..6 (Sat); days since Monday = (day + 6) % 7.
  const daysSinceMonday = (next.getDay() + 6) % 7
  next.setDate(next.getDate() - daysSinceMonday)
  return toLocalISODate(next)
}

function addDays(isoDate: string, days: number) {
  const next = new Date(`${isoDate}T00:00:00`)
  next.setDate(next.getDate() + days)
  return toLocalISODate(next)
}

export function WorkoutExportDialog(config: WorkoutExportDialogConfig) {
  const { messages } = useLocale()
  const [open, setOpen] = useState(false)
  const [mode, setMode] = useState<ExportMode>(config.defaultMode ?? "week")
  const [weekStart, setWeekStart] = useState(() => getWeekStart(new Date()))
  const [subjectId, setSubjectId] = useState<string>("")
  const [programId, setProgramId] = useState<string>("")
  const [isExporting, setIsExporting] = useState(false)
  const [isExportingToSheets, setIsExportingToSheets] = useState(false)
  const [isLoadingPreview, setIsLoadingPreview] = useState(false)
  const [previewLogs, setPreviewLogs] = useState<WorkoutLog[] | null>(null)
  const [error, setError] = useState<string | null>(null)
  const [notice, setNotice] = useState<string | null>(null)

  const selectedSubject = config.subjects?.find((subject) => subject.id === subjectId)

  // Drop any stale preview when the selected range changes.
  useEffect(() => {
    setPreviewLogs(null)
  }, [mode, weekStart, subjectId, programId])

  const selection: ExportSelection = { mode, programId: programId || undefined, subjectId: subjectId || undefined, weekStart }

  const resolveRange = (): ResolvedExportRange | { error: string } => {
    if (mode === "week") {
      return { from: weekStart, label: `week-${weekStart}`, to: addDays(weekStart, 7) }
    }
    return config.resolveProgramRange(selection)
  }

  const resolved = resolveRange()
  const hasRangeError = "error" in resolved
  const needsSubject = Boolean(config.subjects) && !subjectId
  const actionsDisabled = needsSubject || hasRangeError

  const handlePreview = async () => {
    if (isLoadingPreview || actionsDisabled) return
    setError(null)
    setNotice(null)

    const range = resolveRange()
    if ("error" in range) {
      setError(range.error)
      return
    }

    setIsLoadingPreview(true)
    try {
      const logs = await config.loadLogs({ ...selection, range })
      if (logs.length === 0) {
        setPreviewLogs(null)
        setError(messages.workoutPage.exportEmptyRange)
        return
      }
      setPreviewLogs(logs)
    } catch (err) {
      setError(err instanceof Error ? err.message : messages.workoutPage.exportPreviewFailed)
    } finally {
      setIsLoadingPreview(false)
    }
  }

  const handleExport = async () => {
    if (isExporting || actionsDisabled) return
    setError(null)
    setNotice(null)

    const range = resolveRange()
    if ("error" in range) {
      setError(range.error)
      return
    }

    setIsExporting(true)
    try {
      // Reuse already-fetched preview logs when available (cleared on range change).
      const logs = previewLogs ?? (await config.loadLogs({ ...selection, range }))
      if (logs.length === 0) {
        setError(messages.workoutPage.exportEmptyRange)
        return
      }

      const plannedSessions = config.resolvePlannedSessions
        ? await config.resolvePlannedSessions(selection)
        : undefined
      const bodyMetrics = config.loadBodyMetrics
        ? await config.loadBodyMetrics({ ...selection, range })
        : undefined

      const { downloadWorkoutLogs } = await import("@/components/workout-export-excel")
      await downloadWorkoutLogs(logs, {
        bodyMetrics,
        from: range.from,
        label: range.label,
        plannedSessions,
        programStartDate: range.programStartDate,
        subjectName: selectedSubject?.name,
        to: range.to,
      })
      setOpen(false)
    } catch (err) {
      setError(err instanceof Error ? err.message : messages.workoutPage.exportFailed)
    } finally {
      setIsExporting(false)
    }
  }

  const handleExportGoogleSheets = async () => {
    if (isExportingToSheets || actionsDisabled) return
    setError(null)
    setNotice(null)

    const range = resolveRange()
    if ("error" in range) {
      setError(range.error)
      return
    }

    setIsExportingToSheets(true)
    try {
      const result = await config.exportToSheets({ ...selection, range })
      setNotice(`Exported ${result.logCount} workout logs (${result.rowCount} rows) to Google Sheets.`)
    } catch (err) {
      setError(err instanceof Error ? err.message : "Kh├┤ng thß╗â export workout logs sang Google Sheets.")
    } finally {
      setIsExportingToSheets(false)
    }
  }

  const showNoPrograms = mode === "program" && config.showProgramPicker && (config.programs?.length ?? 0) === 0

  return (
    <Dialog
      open={open}
      onOpenChange={(next) => {
        setOpen(next)
        if (!next) {
          setPreviewLogs(null)
          setError(null)
          setNotice(null)
        }
      }}
    >
      <DialogTrigger asChild>
        <Button variant="outline" size="sm" className="gap-2">
          <Download className="h-4 w-4" />
          {config.triggerLabel}
        </Button>
      </DialogTrigger>

      <DialogContent
        overlayClassName={config.dialogOverlayClassName}
        className={cn(previewLogs ? "w-full max-w-md" : "w-full max-w-sm", config.dialogContentClassName)}
      >
        <DialogHeader>
          <DialogTitle>{config.title}</DialogTitle>
        </DialogHeader>

        <div className="mt-2 flex flex-col gap-5">
          {config.description ? (
            <p className="text-sm text-muted-foreground">{config.description}</p>
          ) : null}

          {/* Subject (trainee) picker */}
          {config.subjects ? (
            <div className="flex flex-col gap-2">
              <Label htmlFor="export-subject" className="text-xs text-muted-foreground">
                {config.subjectSelectLabel}
              </Label>
              <select
                id="export-subject"
                value={subjectId}
                onChange={(event) => setSubjectId(event.target.value)}
                className="h-9 w-full rounded-md border border-input bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              >
                <option value="">{config.subjectPlaceholder}</option>
                {config.subjects.map((subject) => (
                  <option key={subject.id} value={subject.id}>
                    {subject.label ?? subject.name}
                  </option>
                ))}
              </select>
            </div>
          ) : null}

          {/* Mode picker */}
          <div className="flex flex-col gap-2">
            <Label className="text-xs text-muted-foreground">{messages.workoutPage.exportFilterBy}</Label>
            <div className="flex gap-2">
              {(["week", "program"] as ExportMode[]).map((value) => (
                <button
                  key={value}
                  type="button"
                  onClick={() => setMode(value)}
                  className={cn(
                    "flex-1 rounded-md border px-3 py-2 text-sm font-medium transition-colors",
                    mode === value
                      ? "border-primary bg-primary-soft text-primary"
                      : "border-border bg-background text-muted-foreground hover:bg-muted",
                  )}
                >
                  {value === "week" ? messages.workoutPage.exportWeek : messages.workoutPage.exportProgram}
                </button>
              ))}
            </div>
          </div>

          {/* Week picker */}
          {mode === "week" ? (
            <div className="flex flex-col gap-2">
              <Label htmlFor="export-week-start" className="text-xs text-muted-foreground">
                {messages.workoutPage.exportWeekStarts}
              </Label>
              <input
                id="export-week-start"
                type="date"
                value={weekStart}
                onChange={(event) => {
                  const value = event.target.value
                  if (value) setWeekStart(getWeekStart(new Date(`${value}T00:00:00`)))
                }}
                className="h-9 w-full rounded-md border border-input bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
              />
              <p className="text-xs text-muted-foreground">
                {messages.workoutPage.exportFromTo(formatDisplayDate(weekStart), formatDisplayDate(addDays(weekStart, 7)))}
              </p>
            </div>
          ) : null}

          {/* Program picker (only when a list of programs is offered) */}
          {mode === "program" && config.showProgramPicker ? (
            <div className="flex flex-col gap-2">
              <Label htmlFor="export-program" className="text-xs text-muted-foreground">
                Program
              </Label>
              {showNoPrograms ? (
                <p className="text-sm text-muted-foreground">{messages.workoutPage.noAssignedPrograms}</p>
              ) : (
                <select
                  id="export-program"
                  value={programId}
                  onChange={(event) => setProgramId(event.target.value)}
                  className="h-9 w-full rounded-md border border-input bg-background px-3 text-sm focus:outline-none focus:ring-2 focus:ring-ring"
                >
                  <option value="">{messages.workoutPage.exportSelectProgram}</option>
                  {config.programs?.map((program) => (
                    <option key={program.id} value={program.id}>
                      {program.name}
                    </option>
                  ))}
                </select>
              )}
            </div>
          ) : null}

          {/* Resolved range hint */}
          {!hasRangeError && mode === "program" ? (
            <p className="text-xs text-muted-foreground">
              {messages.workoutPage.exportFromTo(formatDisplayDate(resolved.from), formatDisplayDate(resolved.to))}
            </p>
          ) : null}

          {error && <p className="text-sm text-destructive-text">{error}</p>}
          {notice && <p className="text-sm text-primary">{notice}</p>}

          {previewLogs ? (
            <div className="flex flex-col gap-2">
              <Label className="text-xs text-muted-foreground">{messages.workoutPage.exportPreview}</Label>
              <WorkoutLogsPreview logs={previewLogs} />
            </div>
          ) : null}

          <div className="flex flex-col gap-2">
            <Button
              variant="outline"
              onClick={() => void handlePreview()}
              disabled={isLoadingPreview || isExporting || actionsDisabled}
              className="w-full gap-2"
            >
              {isLoadingPreview ? <Loader2 className="h-4 w-4 animate-spin" /> : <Eye className="h-4 w-4" />}
              {isLoadingPreview
                ? messages.workoutPage.exportLoading
                : previewLogs
                  ? messages.workoutPage.exportReloadPreview
                  : messages.workoutPage.exportPreview}
            </Button>

            <Button
              onClick={() => void handleExport()}
              disabled={isExporting || isExportingToSheets || actionsDisabled}
              className="w-full gap-2"
            >
              {isExporting ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
              {isExporting ? messages.workoutPage.generatingFile : messages.workoutPage.exportDownloadExcel}
            </Button>
            <Button
              variant="outline"
              onClick={() => void handleExportGoogleSheets()}
              disabled={isExporting || isExportingToSheets || actionsDisabled}
              className="w-full gap-2"
            >
              {isExportingToSheets ? <Loader2 className="h-4 w-4 animate-spin" /> : <Download className="h-4 w-4" />}
              {isExportingToSheets ? "Exporting to Google Sheets..." : "Export to Google Sheets"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  )
}
